// Üretilen dosya: tool/ozgun/uret.py. Sınav Hazırlık · TYT Türkçe: yazım ve noktalama uygulamaları (orta).
const ozExam7Orta = <(String, String, List<String>, String)>[
  ('Aşağıdakilerin hangisinde iki noktadan sonra büyük harf kullanılması yazım kurallarına aykırıdır?', 'Bahçeye üç ağaç diktik: Elma, armut ve ayva.', ['Öğretmen şöyle dedi: Yarın sınav yapılacak.', 'Annem bir uyarıda bulundu: Kapıyı kilitlemeyi unutma.', 'Yazar şunu vurguluyor: Okumak bir alışkanlıktır.'], 'İki noktadan sonra cümle niteliği taşıyan bir söz geliyorsa büyük harfle başlanır. "elma, armut ve ayva" bir cümle değil, sıralamadır; bu yüzden küçük harfle başlamalıdır.'),
  ('Aşağıdaki cümlelerin hangisinde unvan küçük harfle yazılmış ve bu kullanım doğrudur?', 'Muayeneden sonra doktor bana birkaç ilaç yazdı.', ['Açılış konuşmasını profesör Ali Yıldız uzun bir sunumla yaptı.', 'Törene vali Osman Kaya da katıldı.', 'Sahneye avukat Nermin Aksoy davet edildi.'], 'Unvanlar özel addan önce gelip onunla birlikte kullanıldığında büyük harfle başlar. Bir kişi adına bağlanmadan genel anlamda kullanılan "doktor" ise küçük yazılır.'),
  ('"kazak" sözcüğü hem bir giysiyi hem de bir Türk boyunu karşılar. Aşağıdaki cümlelerin hangisinde bu sözcüğün küçük harfle yazılması yanlıştır?', 'Bozkırlarda yaşayan kazaklar at yetiştiriciliğiyle tanınır.', ['Anneannem bana kış için kalın, yünlü ve yakalı bir kazak ördü.', 'Vitrindeki kazakların tümü indirimdeydi.', 'Sabah serin olduğu için kazağımı giydim.'], 'Millet ve boy adları büyük harfle başlar. Bozkırda yaşayan topluluğu anlatan "Kazaklar" bir boy adı olduğundan büyük yazılmalıdır; giysi anlamındaki "kazak" ise cins addır.'),
  ('Gazete ve dergi adlarında "gazete", "dergi" sözcükleri adın parçası değilse küçük yazılır. Aşağıdaki cümlelerin hangisi bu kurala uygundur?', 'Dedem her sabah Cumhuriyet gazetesini baştan sona okur.', ['Ablam her ay Varlık Dergisini kitapçıdan düzenli olarak alır.', 'Bu haber dün Milliyet Gazetesinde yayımlandı.', 'Şiirini Hisar Dergisi\'ne göndermiş.'], '"Cumhuriyet" gazetenin adıdır; "gazete" sözcüğü adın parçası olmadığı için küçük harfle yazılır ve ek doğrudan ona bitişir.'),
  ('Aşağıdaki cümlelerin hangisinde tarihî dönem adı yanlış yazılmıştır?', 'Osmanlı\'da ilk Türk matbaası lale devrinde kurulmuştur.', ['Tanzimat Fermanı 1839\'da ilan edilmiştir.', 'Kurtuluş Savaşı 1922\'de zaferle sonuçlanmıştır.', 'Malazgirt Meydan Muharebesi 1071\'de Anadolu\'nun kapılarını açmıştır.'], 'Tarihî olay, dönem ve çağ adları büyük harfle başlar; doğrusu "Lale Devri"dir. İbrahim Müteferrika\'nın matbaası bu dönemde açılmıştır.'),
  ('Din ve mezhep adlarının yazımı göz önüne alındığında aşağıdaki cümlelerin hangisinde yanlışlık vardır?', 'Roma İmparatorluğu\'nda hristiyanlık 4. yüzyılda resmî din oldu.', ['Budizm, Hindistan\'da ortaya çıkmış bir inanç sistemidir.', 'Oğuz boyları 10. yüzyıldan başlayarak Müslümanlığı benimsemişti.', 'Yahudilik, tek tanrılı dinlerin en eskisi sayılır.'], 'Din ve mezhep adları büyük harfle başlar; doğrusu "Hristiyanlık"tır.'),
  ('Aşağıdaki cümlelerin hangisinde kıta ya da bölge adının bir parçası yanlışlıkla küçük yazılmıştır?', 'Türklerin ana yurdunun orta Asya olduğu kabul edilir.', ['Güney Amerika\'nın en uzun ve en bol sulu ırmağı Amazon\'dur.', 'Kuzey Afrika ülkelerinde çöl iklimi yaygındır.', 'Batı Avrupa\'da okyanus iklimi etkilidir.'], 'Yön ya da konum bildiren sözcük bir yer adının parçası olduğunda büyük harfle başlar: Orta Asya.'),
  ('Aşağıdaki cümlelerin hangisinde kesme işareti yanlış kullanılmıştır?', 'Bu akşam Kemal\'ler bize yemeğe gelecek.', ['Mektubu Selin\'e yarın teslim edeceğim.', 'Bu soruyu Kerem\'den başka çözen olmadı.', 'Tatilimizi Bodrum\'da geçirdik.'], 'Özel adlara getirilen çokluk eki ve ondan sonra gelen ekler kesmeyle ayrılmaz: Kemaller.'),
  ('Kişi adından sonra gelen saygı sözüne ek getirilirken aşağıdakilerden hangisi doğru yazılır?', 'Paketi Ayşe Hanım\'a bıraktım.', ['Paketi Ayşe\'Hanıma bıraktım.', 'Paketi Ayşe Hanıma\' bıraktım.', 'Paketi Ayşe hanıma bıraktım.'], 'Kişi adlarından sonra gelen unvan ve saygı sözleri adla birlikte özel ad sayılır; ek, son sözcükten kesmeyle ayrılır: Ayşe Hanım\'a.'),
  ('Rakamla yazılan sayılara getirilen ekler sayının okunuşuna uyar. Buna göre aşağıdaki cümlelerin hangisinde ek yanlış getirilmiştir?', 'Sınıftaki öğrenci sayısı bu yıl 30\'e ulaştı.', ['Maç 2\'ye 1 sona erdi.', 'Pastayı 6\'ya bölüp herkese dağıttık.', 'Konser akşam saat 9\'da kentin en büyük salonunda başlayacak.'], '30 sayısı "otuz" diye okunur ve son hecesi kalın ünlülüdür; yönelme eki "-a" biçiminde gelir: 30\'a.'),
  ('"Bu konuyu ... biliyor." cümlesinde boş bırakılan yere "baştan sona" anlamını veren harf ifadesi aşağıdakilerin hangisindeki gibi yazılmalıdır?', 'a\'dan z\'ye', ['a\'den z\'ya', 'a\'dan z\'ya', 'adan zye'], 'Harflere getirilen ekler kesmeyle ayrılır ve harfin okunuşuna uyar: "a" kalın ünlülü olduğu için "-dan", "z" (ze) ince ünlülü olduğu için "-ye" alır.'),
  ('"N\'oldu sana, neden bu kadar sessizsin?" cümlesinde kesme işareti hangi amaçla kullanılmıştır?', 'Söyleyişte düşen seslerin yerini belirtmek için', ['Özel ada getirilen eki ayırmak için', 'Kısaltmaya getirilen eki ayırmak için', 'Bir sözü vurgulayarak öne çıkarmak için'], '"Ne oldu" sözünde söyleyiş sırasında düşen ünlünün yeri kesme işaretiyle gösterilmiştir; bu kullanım şiirde ve konuşma aktarımlarında görülür.'),
  ('Harfle yazılan sayıların bitişik yazılması hangi durumda kurala uygundur?', 'Para tutarı çek ve senetlere yazılırken', ['Sayı bir yaşı ya da süreyi bildirirken', 'Sayı cümlenin başında yer alırken', 'Sayı bir sıra bildiren ek alırken'], 'Sayılar normalde ayrı yazılır; ancak çek, senet gibi belgelerde sonradan değiştirilmesin diye harfle yazılan tutar bitişik yazılır.'),
  ('Aşağıdaki sayı içeren sözcüklerden hangisi kurala aykırı olarak bitişik yazılmıştır?', 'otuzbeş', ['kırkayak', 'üçgen', 'onbaşı'], 'Sayılar ayrı yazıldığından "otuz beş" doğrudur. Sayıyla kurulup yeni bir kavramı karşılayan kırkayak, üçgen ve onbaşı ise birleşik sözcüktür, bitişik yazılır.'),
  ('Rakamla yazılmış sıra sayılarının yazımında aşağıdakilerden hangisi yanlıştır?', 'Bu cami 15.inci yüzyılda yapılmıştır.', ['Bu cami 15. yüzyılda yapılmıştır.', 'Bu cami 15\'inci yüzyılda yapılmıştır.', 'Bu cami XV. yüzyılda yapılmıştır.'], 'Rakamla yazılan sıra sayılarında ya yalnız nokta ya da kesmeyle birlikte "-inci" eki kullanılır; nokta ile ek bir arada kullanılmaz.'),
  ('"On dokuzuncu yüzyıl" ifadesi Roma rakamıyla aşağıdakilerin hangisindeki gibi yazılır?', 'XIX. yüzyıl', ['XXI. yüzyıl', 'IXX. yüzyıl', 'XVIIII. yüzyıl'], 'Roma rakamlarında 19, X (10) ile IX\'un (9) yan yana yazılmasıyla gösterilir: XIX. Sıra bildirdiği için sonuna nokta konur.'),
  ('Osmanlı padişahlarının adları sıra sayısıyla birlikte yazılırken aşağıdakilerden hangisi doğrudur?', 'II. Abdülhamit tahta 1876\'da çıktı.', ['II Abdülhamit tahta 1876\'da çıktı.', 'Abdülhamit II. tahta 1876\'da çıktı.', 'II.\'nci Abdülhamit tahta 1876\'da çıktı.'], 'Hükümdar adlarında sıra, addan önce Roma rakamıyla ve noktayla gösterilir: II. Abdülhamit.'),
  ('Aşağıdaki cümlelerin hangisinde birleşik fiil yanlış yazılmıştır?', 'Bu karışık sorunu ancak sen hal edebilirsin.', ['Ödülü teşekkür ederek kabul etti.', 'Kalabalık salonu hızla terk etti.', 'Yardım ettiğin için sana gerçekten çok minnettarım.'], '"hal" sözcüğü "etmek" ile birleşirken ses türemesine uğrar (hall); bu durumda birleşik fiil bitişik yazılır: halletmek.'),
  ('Aşağıdaki birleşik fiillerden hangisi birleşme sırasında ses türemesine uğradığı için bitişik yazılır?', 'hissetmek', ['kabul etmek', 'terk etmek', 'yardım etmek'], '"his" sözcüğü "etmek" ile birleşirken "s" ünsüzü türer: hissetmek. Öbürlerinde ses olayı olmadığından sözcükler ayrı yazılır.'),
  ('Aşağıdaki birleşik fiillerden hangisi herhangi bir ses olayına uğramadığı için ayrı yazılır?', 'arz etmek', ['emretmek', 'nakletmek', 'zannetmek'], '"arz etmek" birleşirken ses değişikliği olmaz, ayrı yazılır. "emretmek" ve "nakletmek"te ünlü düşmesi, "zannetmek"te ünsüz türemesi vardır.'),
  ('Aşağıdaki cümlelerin hangisinde ses olayı gerçekleştiği hâlde birleşik fiil ayrı yazılarak yanlışlık yapılmıştır?', 'Davetiyeyi kibarca ret etti.', ['Gelişmeleri dikkatle takip etti.', 'Sözünü hiç tereddüt etmeden tuttu.', 'Yaşlı adama yol tarif etti.'], '"ret" sözcüğü "etmek" ile birleşirken ses türemesine uğrar ve sözcükler bitişik yazılır: reddetti.'),
  ('Yaklaşma anlamı veren "-a/-e yazmak" yapısıyla kurulan birleşik fiiller bitişik yazılır. Buna göre aşağıdaki cümlelerin hangisinde yazım yanlışı vardır?', 'Buzlu yolda yürürken az kalsın düşe yazdım.', ['Haberi duyunca olduğu yerde bakakaldı.', 'Uzun yolculuktan sonra koltukta uyuyakalmış.', 'Gürültüyü duymazdan gelip okumayı sürdürdü.'], '"-a yazmak" yapısındaki birleşik fiil yaklaşma (az kalsın olma) anlamı taşır ve bitişik yazılır: düşeyazdım.'),
  ('Aşağıdakilerden hangisi bitişik yazılması gerekirken ayrı yazılmıştır?', 'kuş konmaz', ['ders kitabı', 'çay bahçesi', 'yemek masası'], '"kuşkonmaz" sözcükleri gerçek anlamından uzaklaşarak bir bitkiyi adlandırdığı için bitişik yazılır. Öbürleri anlam kayması olmayan ad tamlamalarıdır, ayrı yazılır.'),
  ('"Aslanağzı" sözcüğünün bitişik yazılmasının nedeni aşağıdakilerden hangisidir?', 'Sözcüklerin gerçek anlamından uzaklaşıp bir bitkiyi adlandırması', ['Birleşme sırasında bir ünlünün düşmesi', 'İki sözcüğün de hayvan adı olması', 'Sözcüklerden birinin yabancı kökenli olması'], 'Bitki, hayvan ve nesne adlarında sözcükler gerçek anlamlarını yitirip yeni bir kavramı karşılıyorsa birleşik sözcük bitişik yazılır.'),
  ('Aşağıdaki cümlelerin hangisinde "ev" sözcüğüyle kurulmuş birleşik ad, ayrı yazılarak yanlışlığa yol açmıştır?', 'Romanın ilk baskısını küçük bir yayın evi yapmış.', ['Yazları dedemin köy evinde kalırız.', 'Hafta sonu huzurevindeki yaşlıları ziyaret edip onlarla sohbet ettik.', 'Babaannemin evi geniş bir bahçenin ortasındaydı.'], '"yayınevi" bir kurumu karşılayan kalıplaşmış birleşik addır ve bitişik yazılır. "köy evi" ise köyde bulunan bir evi anlatan ad tamlamasıdır, ayrı yazılır.'),
  ('Aşağıdaki cümlelerin hangisinde yazım yanlışı vardır?', 'Deprem zedelere yardım için bir kampanya başlatıldı.', ['Kazazedeler sahile sağ salim çıkarıldı.', 'Evliya Çelebi\'nin seyahatnamesi on ciltten oluşan büyük bir eserdir.', 'Misafirperver komşularımız bizi çok iyi ağırladı.'], 'Farsça "-zede, -name, -perver" gibi sözcüklerle kurulan birleşik sözcükler bitişik yazılır: depremzede.'),
  ('"Bir yapının, kurumun ya da sistemin temelini oluşturan şeylerin bütünü" anlamındaki sözcük aşağıdakilerin hangisindeki gibi yazılır?', 'altyapı', ['alt yapı', 'alt-yapı', 'altyapısal'], 'Bu kavram tek bir anlamı karşılayan birleşik sözcüktür ve bitişik yazılır: altyapı.'),
  ('"Delikanlı" sözcüğünün tek sözcük gibi bitişik yazılmasının gerekçesi aşağıdakilerden hangisidir?', 'Oluşturan sözcüklerin anlamından tümüyle farklı bir kavramı karşılaması', ['İki sözcüğün de sıfat olması', 'Sözcüklerden birinde ünsüz türemesi olması', 'Sözcüğün yabancı bir dilden alınmış olması'], '"Deli" ve "kanlı" sözcükleri birleşerek "genç erkek" anlamını kazanmıştır; anlam kayması olan birleşik sözcükler bitişik yazılır.'),
  ('Yazım kılavuzuna göre aşağıdaki cümlelerin hangisinde ayrı yazılması gereken bir söz bitişik yazılmıştır?', 'Tatilden döndüğümüzde evde herşey yerli yerindeydi.', ['Biraz dinlendikten sonra yola devam ettik.', 'Kapı birdenbire açılınca hepimiz irkildik.', 'Kardeşler birbirine çok bağlıydı.'], '"her şey" iki ayrı sözcükten oluşur ve ayrı yazılır. "biraz, birdenbire, birbiri" ise bitişik yazılır.'),
  ('Aşağıdaki sözlerden hangisi bitişik yazıldığında yazım yanlışı olur?', 'her biri', ['birbiri', 'birlikte', 'birdenbire'], '"her biri" ayrı yazılır; "birbiri, birlikte, birdenbire" ise kalıplaşmış oldukları için bitişik yazılır.'),
  ('"bütün" sözcüğünün pekiştirmeli biçimi aşağıdakilerin hangisinde doğru yazılmıştır?', 'büsbütün', ['bütbütün', 'büpbütün', 'bümbütün'], '"bütün" sözcüğü "s" pekiştirme sesiyle pekiştirilir: büsbütün.'),
  ('"m" sesiyle kurulan ikilemeler düşünüldüğünde aşağıdaki cümlelerin hangisinde yazım doğrudur?', 'Aceleyle çıkarken çanta manta her şeyi evde unutmuş.', ['Aceleyle çıkarken çantamanta her şeyi evde unutmuş.', 'Aceleyle çıkarken çanta-manta her şeyi evde unutmuş.', 'Aceleyle çıkarken çanta, manta her şeyi evde unutmuş.'], '"m" ile kurulan ikilemeler de öbür ikilemeler gibi ayrı yazılır ve araya noktalama işareti konmaz.'),
  ('Aşağıdaki cümlelerin hangisinde "-ır ... -maz" kalıbıyla kurulan söz yanlış yazılmıştır?', 'Eve girergirmez çantasını bırakıp mutfağa koştu.', ['Zil çalar çalmaz öğrenciler koridordan sınıflarına girdi.', 'Haberi alır almaz yola çıktık.', 'Güneş doğar doğmaz tarlaya gittiler.'], '"-ır ... -maz" yapısıyla kurulan zarf-fiil ikilemeleri ayrı yazılır: girer girmez.'),
  ('Aşağıdaki cümlelerin hangisinde sıfat yapan "-ki" eki yanlışlıkla ayrı yazılmıştır?', 'Akşam ki toplantıya bütün çalışanlar katılacak.', ['Masadaki kitapları akşam olmadan rafa kaldırmayı unutma.', 'Yarınki maç için biletler tükendi.', 'Bahçedeki gülleri annem dikmişti.'], 'Zaman ve yer bildiren sözcüklere gelerek sıfat oluşturan "-ki" ekidir ve bitişik yazılır: akşamki.'),
  ('Aşağıdaki cümlelerin hangisinde "de" bağlacının yazımında yanlışlık vardır?', 'Hafta sonu toplantısına Selim\'de katıldı.', ['Toplantıda yeni kararlar alındı.', 'Sen de bu hafta sonu bizimle pikniğe gelmek ister misin?', 'Ankara\'da kar yağışı etkili oldu.'], 'Bağlaç olan "de", özel addan sonra gelse bile ayrı yazılır ve kesme işareti almaz: Selim de katıldı.'),
  ('Aşağıdaki cümlelerin hangisinde "de" bağlacı, kendinden önceki sözcüğün sert ünsüzle bitmesi nedeniyle yanlış yazılmıştır?', 'Çantama kitap ta koydum, defter de.', ['Kitapta çok ilginç ve düşündürücü bir bölüm buldum.', 'Ağaçta bir kuş yuvası gördük.', 'Sokakta çocuklar oynuyordu.'], 'Bağlaç olan "de" ünsüz benzeşmesine uğramaz, her zaman "de/da" biçiminde yazılır: kitap da.'),
  ('Bir cümledeki "de" sözcüğünün bağlaç mı, bulunma eki mi olduğunu anlamak için aşağıdaki yollardan hangisi kullanılır?', 'Cümleden çıkarıldığında anlamın bozulmadığına bakmak', ['Sözcüğün büyük harfle başlayıp başlamadığına bakmak', 'Cümlenin sonuna soru eki getirip anlamı denemek', 'Sözcüğün başına kesme işareti koyup okumak'], 'Bağlaç olan "de" cümleden çıkarıldığında anlam daralsa da cümle bozulmaz; bulunma eki çıkarıldığında ise cümle anlamsızlaşır. Yerine "dahi" de getirilebilir.'),
  ('Soru ekinden sonra gelen kişi ekleri düşünüldüğünde aşağıdaki cümlelerin hangisinde yazım doğrudur?', 'Bu akşamki davete siz de gelecek misiniz?', ['Bu akşamki davete siz de gelecek mi siniz?', 'Bu akşamki davete siz de gelecekmisiniz?', 'Bu akşamki davete siz de gelecek mi-siniz?'], '"mi" kendinden önceki sözcükten ayrı yazılır; kendinden sonra gelen kişi ekleri ise "mi"ye bitişik yazılır: gelecek misiniz.'),
  ('"Ayşe ile" sözü "ile" bitişik yazılarak kısaltıldığında doğru biçim hangisi olur?', 'Ayşe\'yle', ['Ayşe\'le', 'Ayşeyle', 'Ayşe\'yla'], 'Ünlüyle biten sözcüklere "ile" bitiştiğinde araya "y" girer ve ek ünlü uyumuna uyar; özel ada geldiği için kesmeyle ayrılır.'),
  ('"Bu çocuk çalışkan ise sınavı kazanır." cümlesinde "ise" ek olarak kullanılıp sözcüğe bitiştirilirse "çalışkan ise" sözü nasıl yazılır?', 'çalışkansa', ['çalışkanyse', 'çalışkanse', 'çalışkan\'sa'], 'Ek-fiilin şart çekimi "ise" bitişik yazılınca "i" düşer ve ek, sözcüğün son ünlüsüne uyar: çalışkansa.'),
  ('"-ken" eki ünlü uyumuna girmez. Buna göre aşağıdaki cümlelerin hangisinde yazım yanlışı vardır?', 'Otobüsteykan uyuyakalınca durağı kaçırmış.', ['Annem pazardayken yağmur bastırdı.', 'Ödevimi yaparken müzik dinlerim.', 'Okuldayken öğretmenimiz bize mektup okudu.'], '"-ken" eki ünlü uyumuna uymaz, her zaman "-ken" biçiminde yazılır: otobüsteyken.'),
  ('"âdet" ve "adet" sözcükleri farklı anlamlar taşır. Aşağıdaki cümlelerin hangisinde bu sözcüklerden biri yanlış yazılmıştır?', 'Garson masaya beş âdet çatal ve bıçak getirdi.', ['Bayramda büyüklerin elini öpmek eski bir âdettir.', 'Bu çiftlikte yüz adet koyun var.', 'Her yıl aynı âdeti sürdürüyorlar.'], '"âdet" gelenek, görenek; "adet" ise sayı, tane anlamındadır. Sayı bildiren yerde düzeltme işareti kullanılmaz.'),
  ('Akrabalık ya da yakınlık bildiren "-gil" ekinin yazımı göz önüne alındığında aşağıdaki cümlelerin hangisinde yanlışlık vardır?', 'Bayramın ikinci günü dayım gile gittik.', ['Hafta sonunu yağmur yüzünden teyzemgilde geçirdik.', 'Akşam yemeğine amcamgil gelecek.', 'Bu yaz halamgille tatile çıkacağız.'], '"-gil" bir ektir ve getirildiği sözcüğe bitişik yazılır: dayımgile.'),
  ('Zaman bildiren sözcüklere gelen "-leyin" eki ünlü uyumuna girmez. Buna göre hangisinin yazımı doğrudur?', 'sabahleyin', ['sabahlayın', 'sabah leyin', 'sabahlıyın'], '"-leyin" eki kalın ünlülü sözcüklere gelse de değişmeden yazılır: sabahleyin, akşamleyin.'),
  ('"Gösterişten uzak, alçak gönüllü" anlamındaki sözcük aşağıdakilerin hangisindeki gibi yazılır?', 'mütevazı', ['mütevazi', 'mütavazı', 'mütevazü'], 'Arapça kökenli bu sözcüğün yazım kılavuzundaki biçimi "mütevazı"dır.'),
  ('"Uçağın kalkışı kötü hava nedeniyle bir saat ... yaptı." cümlesinde boş bırakılan yere getirilecek sözcüğün doğru yazımı hangisidir?', 'rötar', ['rötör', 'rotar', 'röttar'], '"Gecikme" anlamındaki Fransızca kökenli sözcük "rötar" biçiminde yazılır.'),
  ('"Berberde saç ve sakal ... olmak" sözündeki boşluğa gelecek sözcüğün yazım kılavuzundaki biçimi hangisidir?', 'tıraş', ['traş', 'tiraş', 'tıraşş'], 'Farsça kökenli sözcüğün yazım kılavuzundaki biçimi "tıraş"tır.'),
  ('Kahve ve çayda bulunan, uyarıcı etkisi olan maddenin adı aşağıdakilerin hangisindeki gibi yazılır?', 'kafein', ['kafeyin', 'kaffein', 'kafeinn'], 'Bu maddenin adı Türkçede "kafein" biçiminde yazılır.'),
  ('"Sanatla, düşünceyle uğraşan; aydın" anlamındaki Fransızca kökenli sözcüğün doğru yazımı hangisidir?', 'entelektüel', ['entellektüel', 'entelektüal', 'entelaktüel'], 'Sözcüğün yazım kılavuzundaki biçimi "entelektüel"dir.'),
  ('Kitap, gazete gibi yayınların basıldığı yer anlamındaki sözcük nasıl yazılır?', 'matbaa', ['matbağa', 'matba', 'mattbaa'], 'Arapça kökenli sözcük iki "a" ile yazılır: matbaa.'),
  ('"Uzun bir ... sonra kente geri döndük." cümlesindeki boşluğa gelecek sözcük yazım kurallarına göre hangisidir?', 'seyahatten', ['seyehatten', 'seyahetten', 'seyahadtan'], 'Arapça kökenli sözcük "seyahat" biçiminde yazılır; ek aldığında da bu biçim korunur.'),
  ('Belirli aralıklarla tekrarlanan süre anlamındaki sözcük aşağıdakilerin hangisinde doğru yazılmıştır?', 'periyot', ['periyod', 'peryot', 'periyöt'], 'Fransızca kökenli sözcüklerin sonundaki "d" Türkçede "t"ye döner: periyot. Benzer biçimde "metot" da "t" ile yazılır.'),
  ('Hediye paketlerini süslemekte kullanılan ince şeridin adı nasıl yazılır?', 'kurdele', ['kurdela', 'kordele', 'kurdelle'], 'Sözcüğün yazım kılavuzundaki biçimi "kurdele"dir.'),
  ('Ceketin üstüne giyilen, ince kumaştan yapılmış uzun dış giysinin adı aşağıdakilerin hangisindeki gibi yazılır?', 'pardösü', ['pardesü', 'pardüsü', 'pardesö'], 'Fransızca kökenli sözcük "pardösü" biçiminde yazılır; "pardesü" yaygın bir yanlıştır.'),
  ('"Kuşatılmış, bulunduğu yerden çıkamaz durumda kalmış" anlamındaki sözcük aşağıdaki cümlelerin hangisinde doğru yazılmıştır?', 'Yoğun kar nedeniyle yolcular dağ köyünde mahsur kaldı.', ['Yoğun kar nedeniyle yolcular dağ köyünde mahzur kaldı.', 'Yoğun kar nedeniyle yolcular dağ köyünde mahsor kaldı.', 'Yoğun kar nedeniyle yolcular dağ köyünde mahzür kaldı.'], '"mahsur" bir yerde kuşatılmış, çıkamaz durumda kalmış demektir. "mahzur" ise sakınca anlamına gelir ve farklı bir sözcüktür.'),
  ('"tabii" (elbette, doğal) ve "tabi" (bağlı, uyan) sözcükleri karıştırılmaktadır. Aşağıdaki cümlelerin hangisinde bu sözcüklerden biri yanlış yazılmıştır?', 'Tabi ki doğum gününe ben de geleceğim.', ['Bu kurala okuldaki herkes tabidir.', 'Ormanın tabii güzelliği bizi büyüledi.', 'Tabii, istersen seni de arabayla oraya götürürüz.'], '"elbette" anlamında kullanılan sözcük iki "i" ile yazılır: Tabii ki. "tabi" ise "bağlı" anlamındadır.'),
  ('Okulun laboratuvarında (I) bir makinenin (II) egzosundan (III) çıkan dumanı inceleyip sonuçları kontrol (IV) ettik. Bu cümledeki numaralanmış sözcüklerden hangisinin yazımı yanlıştır?', 'III', ['I', 'II', 'IV'], 'Doğru yazım "egzoz"dur; ek aldığında da "egzozundan" biçiminde yazılır.'),
  ('Mağazamızda bilumum (I) kırtasiye malzemesi, pantolon (II), kapüşonlu (III) mont ve aksesuvar (IV) bulunur. Bu cümledeki numaralanmış sözcüklerden hangisinin yazımı yanlıştır?', 'IV', ['I', 'II', 'III'], 'Fransızcadan geçen sözcüğün doğru yazımı "aksesuar"dır.'),
  ('Müzede dinazor (I) iskeletini gören çocuklar çok şaşırdı; rehber fotoğraf (II) çekmenin yasak olduğunu söyleyince hepsi "Pekâlâ (III)" deyip defterlerine not almaya (IV) başladı. Bu cümledeki numaralanmış sözcüklerden hangisinin yazımı yanlıştır?', 'I', ['II', 'III', 'IV'], 'Sözcüğün doğru yazımı "dinozor"dur.'),
  ('Eşkiya (I) hikâyelerini anlatan bu romanı atölye (II) çalışmasında kompozisyon (III) ödevi olarak okuduk ve herkes (IV) çok beğendi. Bu cümledeki numaralanmış sözcüklerden hangisinin yazımı yanlıştır?', 'I', ['II', 'III', 'IV'], 'Sözcüğün doğru yazımı "eşkıya"dır.'),
  ('Ressam kilisenin duvarındaki mozayik (I) parçalarını inceledi; bu sırada orkestra (II) salonda prova yapıyordu ve sandviç (III) molası verilince herkes dışarı çıktı (IV). Bu cümledeki numaralanmış sözcüklerden hangisinin yazımı yanlıştır?', 'I', ['II', 'III', 'IV'], 'Sözcüğün doğru yazımı "mozaik"tir.'),
  ('Konferansta konuşan profesör, hiç tereddüt (I) etmeden enterasan (II) bir örnek verdi ve salondaki herkesin (III) dikkatini çekti (IV). Bu cümledeki numaralanmış sözcüklerden hangisinin yazımı yanlıştır?', 'II', ['I', 'III', 'IV'], 'Fransızca kökenli sözcük "enteresan" biçiminde yazılır.'),
  ('Kapıda bekleyen hanım efendi (I), kız kardeşinin (II) yeni evinin adresini sordu (III) ve teşekkür ederek ayrıldı (IV). Bu cümledeki numaralanmış sözcüklerden hangisinin yazımı yanlıştır?', 'I', ['II', 'III', 'IV'], 'Saygı bildiren "hanımefendi" kalıplaşmış birleşik sözcüktür ve bitişik yazılır. "kız kardeş" ise ayrı yazılır.'),
  ('Malesef (I) uçağımız rötar (II) yaptı; havalimanındaki (III) kafeteryada (IV) iki saat bekledik. Bu cümledeki numaralanmış sözcüklerden hangisinin yazımı yanlıştır?', 'I', ['II', 'III', 'IV'], 'Arapça kökenli sözcüğün doğru yazımı "maalesef"tir.'),
  ('Bir hafta sonra montumu almaya gittiğimde terzi (I) bozuk (II) fermuvarı (III) çoktan değiştirmişti (IV). Bu cümledeki numaralanmış sözcüklerden hangisinin yazımı yanlıştır?', 'III', ['I', 'II', 'IV'], 'Sözcüğün doğru yazımı "fermuar"dır; araya "v" sesi girmez.'),
  ('Öğretmenimiz deney (I) sonuçlarını (II) not ettikten sonra bizi (III) laboratuara (IV) götürdü. Bu cümledeki numaralanmış sözcüklerden hangisinin yazımı yanlıştır?', 'IV', ['I', 'II', 'III'], 'Yazım kılavuzunda kabul edilen biçim "laboratuvar"dır.'),
  ('Konuşmacı salondaki öğrencilere dönüp "Hiçkimse (I) bu soruyu (II) tek başına çözemez (III), birlikte düşünelim (IV)." dedi. Bu cümledeki numaralanmış sözcüklerden hangisinin yazımı yanlıştır?', 'I', ['II', 'III', 'IV'], '"hiç kimse" iki ayrı sözcükten oluşur ve ayrı yazılır.'),
  ('Yer yüzündeki (I) canlıların büyük bölümü (II) denizlerde yaşar; denizaltıların (III) keşfettiği türler bunun kanıtıdır (IV). Bu cümledeki numaralanmış sözcüklerden hangisinin yazımı yanlıştır?', 'I', ['II', 'III', 'IV'], '"yeryüzü" kalıplaşmış birleşik sözcüktür ve bitişik yazılır; "denizaltı" da bitişiktir.'),
  ('"Atatürk 19.05.1919 tarihinde Samsun\'a çıktı." cümlesinde noktanın kullanım amacı aşağıdakilerin hangisinde de vardır?', 'Belgenin altına 12.04.2021 tarihini attı.', ['Bu yarışmada 1. olan öğrenci ödül aldı.', 'Konser 20.30\'da başlayacak.', 'Prof. Dr. Ahmet Bey konferans verdi.'], 'Örnek cümlede nokta, tarih yazımında gün, ay ve yıl bildiren sayıları ayırmak için kullanılmıştır; aynı kullanım tarih bildiren seçenekte vardır.'),
  ('Rakamla yazılmış sıra sayılarının ardından konan nokta ile ilgili aşağıdakilerden hangisi doğrudur?', 'Sayının sıra bildirdiğini gösterir ve "-inci" ekinin yerini tutar.', ['Sayının ondalık kısmını tam kısmından ayırır.', 'Sayıyı kendisinden sonra gelen addan ayırmak için konur.', 'Sayının yaklaşık bir değer olduğunu belirtir.'], '"5. sınıf" yazımında nokta "beşinci" anlamını verir; bu yüzden nokta ile "-inci" eki birlikte kullanılmaz.'),
  ('Aşağıdaki cümlelerin hangisinde virgül, tırnak içine alınmadan aktarılan bir sözü cümlenin geri kalanından ayırmak için kullanılmıştır?', 'Yarın biraz geç kalabilirim, dedi annem.', ['Annem biraz geç kalacağını söyledi.', 'Annem, yorgun olduğu için erken yattı.', 'Annemin dediği gibi, erken yatmalıyız.'], 'Tırnak işareti kullanılmadan aktarılan sözlerden sonra virgül konur: ... kalabilirim, dedi annem.'),
  ('"Yaşlı adama baktı." ve "Yaşlı, adama baktı." cümleleri arasındaki anlam farkını oluşturan virgül hangi amaçla kullanılmıştır?', 'Cümlenin ögelerini birbirine karıştırmamak için', ['Seslenilen kişiyi cümlenin geri kalanından ayırmak için', 'Sıralı cümleleri ayırmak için', 'Ara sözü belirtmek için'], 'İkinci cümlede virgül, "yaşlı" sözcüğünün özne olduğunu gösterir; virgülsüz cümlede ise "yaşlı" sözcüğü "adam"ı niteleyen bir sıfattır.'),
  ('Aşağıdaki cümlelerin hangisinde virgül, yüklemden uzak düşmüş özneyi belirtmek amacıyla kullanılmıştır?', 'Çocukluğumu geçirdiğim o eski taş ev, yıllar sonra bir müzeye dönüştürüldü.', ['Sabah erkenden kalktık, kahvaltımızı yapıp yola çıktık.', 'Evet, bu konuda sana katılıyorum.', 'Kardeşim, buraya gel ve şu ağır kutuyu benimle birlikte taşı.'], 'Uzun cümlelerde özneyi yüklemden ayıran söz öbeklerinin çok olması durumunda özne virgülle belirtilir.'),
  ('Akşam olunca da (I) şömine başında oturduk (II) masallar dinledik (III) çay içtik (IV) uzun uzun sohbet ettik. Bu cümlede numaralanmış yerlerden hangisine virgül konması gerekmez?', 'I', ['II', 'III', 'IV'], 'II, III ve IV numaralı yerler sıralı cümleleri ayırdığı için virgül alır. I numaralı yerde zarf ile cümlenin geri kalanı arasında bir ayrım gerekmez.'),
  ('"Erkek çocuklara Ali, Ahmet, Mehmet ( ) kız çocuklara Ayşe, Fatma, Zeynep adını verdiler." cümlesinde ayraçla gösterilen yere hangi işaret konmalıdır?', 'Noktalı virgül', ['Virgül', 'İki nokta', 'Üç nokta'], 'Kendi içinde virgülle ayrılmış farklı tür ya da kümeleri birbirinden ayırmak için noktalı virgül kullanılır.'),
  ('Aşağıdaki cümlelerin hangisinde üç nokta, sözün sonunu getirmeyip okura bırakmak için kullanılmıştır?', 'Keşke o gün sözünü dinleseydim...', ['Ben... şey... aslında bilmiyorum.', 'Sepete elma, armut, ayva... ne varsa koydu.', '"Bir ihtiyar (...) kapıda bekliyordu."'], 'Tamamlanmamış cümlelerin sonunda üç nokta konur. Öbürlerinde duraksama, sıralamanın sürdüğü ve alıntıda atlanan bölüm gösterilmiştir.'),
  ('Başka bir metinden yapılan alıntıda atlanan bölümü göstermek için hangi yazım kullanılır?', 'Ayraç içine alınmış üç nokta', ['Tırnak içine alınmış kısa çizgi', 'Köşeli ayraç içinde soru işareti', 'Arka arkaya iki eğik çizgi'], 'Alıntılarda alınmayan, atlanan kelime ya da bölümlerin yerine ayraç içinde üç nokta konur: (...)'),
  ('Aşağıdaki cümlelerin hangisinde soru işaretinin kullanımı yanlıştır?', 'Bu sorunun cevabını kimin bildiğini merak ediyorum?', ['Kim bilir, belki yarın görüşürüz.', 'Sence bu planı kim hazırladı?', 'Hangi yoldan gitmemiz daha kısa olur?'], '"merak ediyorum" yüklemli cümle bir soru sormaz, bir durumu bildirir; soru anlamı yan cümlede kaldığı için sonuna nokta konmalıdır.'),
  ('Aşağıdaki cümlelerin hangisinde tırnak işareti, özellikle belirtilmek istenen bir sözü göstermek için kullanılmıştır?', 'Bu yazıda "insan" kavramını farklı açılardan ele alacağız.', ['Annem "Erken gel." dedi.', 'Atatürk "Yurtta sulh, cihanda sulh." demiştir.', 'Öğretmen "Kitaplarınızı açın." diye seslendi.'], 'Öbür cümlelerde tırnak, başkasından aktarılan sözü gösterir. İlk cümlede ise üzerinde durulan bir kavram tırnakla belirtilmiştir.'),
  ('Tırnak içinde verilen bir aktarmanın içinde yeniden tırnak kullanmak gerektiğinde hangi işaret kullanılır?', 'Tek tırnak', ['Köşeli ayraç', 'Kesme işareti', 'Eğik çizgi'], 'Tırnak içinde ikinci bir aktarma ya da vurgu gerekiyorsa tek tırnak kullanılır: "Öğretmen \'Yarın sınav var.\' dedi." diye anlattı.'),
  ('Aşağıdaki cümlelerin hangisinde tırnak içindeki sözün yazımı doğrudur?', 'Babam "Akşam yemeğe misafir gelecek." dedi.', ['Babam "Akşam yemeğe misafir gelecek.", dedi.', 'Babam "Akşam yemeğe misafir gelecek". dedi.', 'Babam, "Akşam yemeğe misafir gelecek" dedi.'], 'Tırnak içindeki aktarma cümlesi büyük harfle başlar; sonundaki nokta tırnağın içinde kalır.'),
  ('Satır sonuna sığmayan "öğretmenler" sözcüğü aşağıdaki biçimlerin hangisinde bölünemez?', 'öğr-etmenler', ['öğ-retmenler', 'öğret-menler', 'öğretmen-ler'], 'Satır sonunda sözcükler hece sınırından bölünür. "öğ-ret-men-ler" hecelerine göre "öğr-" bir hece değildir.'),
  ('Aşağıdaki cümlelerin hangisinde ayraç, kendinden önceki sözü açıklamak için kullanılmıştır?', 'Ahmet Haşim, "Piyale" (1926) adlı kitabını yayımladı.', ['Haftaya sınav var (galiba).', '1) Kitapları topla. 2) Masayı sil.', 'Bu kadar zengin (!) bir adamı ömrümde hiç görmedim.'], 'Ayraç içindeki yıl, kitabın yayımlandığı tarihi açıklar. Öbür seçeneklerde ayraç tereddüt, madde sırası ve alay bildirmek için kullanılmıştır.'),
  ('Ayraç içinde yeniden ayraç kullanılması gerektiğinde ikinci ayraç için hangi işaret kullanılır?', 'Köşeli ayraç', ['Tırnak işareti', 'Uzun çizgi', 'Eğik çizgi'], 'Yazım kılavuzuna göre ayraç içinde ayraç gerektiğinde köşeli ayraç kullanılır.'),
  ('Düzyazı içinde yan yana yazılan şiir dizelerini birbirinden ayırmak için hangi işaret kullanılır?', 'Eğik çizgi', ['Kısa çizgi', 'Noktalı virgül', 'Denden'], 'Şiir dizeleri yan yana yazıldığında dize sonları eğik çizgiyle gösterilir: "Ben giderim adı kalır / Dostlar beni hatırlasın".'),
  ('Türkiye Cumhuriyeti\'nde 1926\'da Türk Medeni Kanunu (I) kabul edildi; 1934\'te soyadı kanunu (II) çıkarıldı, Atatürk (III) soyadı da bu dönemde Mustafa Kemal\'e (IV) verildi. Bu cümlede numaralanmış yerlerden hangisinde yazım yanlışı vardır?', 'II', ['I', 'III', 'IV'], 'Yasa adlarının her sözcüğü büyük harfle başlar: Soyadı Kanunu.'),
  ('Millî Mücadele dönemindeki toplantılardan söz eden aşağıdaki cümlelerin hangisinde kongre adı yanlış yazılmıştır?', 'Temsil Heyeti ilk kez erzurum kongresinde oluşturuldu.', ['Sivas Kongresi\'nde bütün cemiyetler birleştirildi.', 'Amasya Genelgesi\'nde millî iradeye vurgu yapıldı.', 'Balıkesir Kongresi\'nde Batı Anadolu\'daki direniş ele alındı.'], 'Tarihî toplantı ve kongre adları büyük harfle başlar: Erzurum Kongresi.'),
  ('Aşağıdaki cümlelerin hangisinde millet adından türeyen bir sıfatın küçük harfle yazılması yanlıştır?', 'Misafirlere köpüklü bir türk kahvesi ikram edildi.', ['Bu odada dedemden kalma, el dokuması eski bir İran halısı serili.', 'Kahvaltıda Ezine peyniri yedik.', 'Annem bize Japon gülü dikti.'], 'Millet ve yer adları, kendilerinden sonra gelen cins adla birlikte kullanılsa da büyük harfle başlar: Türk kahvesi.'),
  ('Aşağıdaki cümlelerin hangisinde büyük harfle başlaması gereken bir ödül ya da yarışma adı küçük yazılmıştır?', 'Orhan Pamuk 2006 yılında nobel edebiyat ödülünü kazandı.', ['Bu yıl okulumuzda bütün sınıfların katıldığı bir şiir yarışması düzenlendi.', 'Yarışmada birinci olan öğrenciye ödül verildi.', 'Ödül töreni okul bahçesinde yapıldı.'], 'Belirli bir ödülün adı özel addır, her sözcüğü büyük harfle başlar: Nobel Edebiyat Ödülü.'),
  ('Aşağıdaki cümlelerin hangisinde kıta ya da okyanus adı yanlış yazılmıştır?', 'Macellan\'ın gemileri büyük okyanus\'u aşarak Asya\'ya ulaştı.', ['Atlas Okyanusu Avrupa ile Amerika\'yı ayırır.', 'Antarktika kıtası yılın büyük bölümünde kalın buzlarla kaplıdır.', 'Hint Okyanusu\'nun kıyısında pek çok ülke vardır.'], 'Okyanus adları özel ad olarak her sözcüğü büyük harfle yazılır: Büyük Okyanus.'),
  ('"hoş" sözcüğüyle kurulan aşağıdaki sözlerden hangisi kalıplaşıp tek kavramı karşıladığı için bitişik yazılır?', 'hoşgörü', ['hoş geldin', 'hoşça kal', 'hoş bulduk'], '"hoşgörü" anlam bütünlüğü kazanmış birleşik addır ve bitişik yazılır. Karşılama ve uğurlama sözleri ise ayrı yazılır.'),
  ('Arasıra (I) bize uğrayan halam, akşamüstü (II) geldiğinde yanında karabiber (III) ve tavukgöğsü (IV) getirirdi. Bu cümlede numaralanmış sözcüklerden hangisinin yazımı yanlıştır?', 'I', ['II', 'III', 'IV'], '"ara sıra" ikileme niteliğinde bir zarftır ve ayrı yazılır. "akşamüstü, karabiber, tavukgöğsü" ise bitişik yazılan birleşik sözcüklerdir.'),
  ('Polis (I) hırsızı suç üstü (II) yakaladı ve olay yerine (III) gelen ekiplere (IV) teslim etti. Bu cümlede numaralanmış sözlerden hangisinin yazımı yanlıştır?', 'II', ['I', 'III', 'IV'], '"Suçun işlendiği anda" anlamındaki birleşik sözcük bitişik yazılır: suçüstü.'),
  ('Bayramda babaannemi (I), anneannemi (II) ve büyük babamı (III) ziyaret ettikten sonra kayınpederini (IV) görmeye giden babamla eve döndük. Bu cümlede numaralanmış akrabalık adlarından hangisinin yazımı yanlıştır?', 'III', ['I', 'II', 'IV'], 'Akrabalık bildiren "büyükbaba, babaanne, anneanne, kayınpeder" kalıplaşmış birleşik sözcüklerdir ve bitişik yazılır.'),
  ('Ne yazıkki (I) iki ülke ateşkes (II) imzaladıktan sonra şehirde (III) çatışmalar yeniden (IV) başladı. Bu cümlede numaralanmış sözlerden hangisinin yazımı yanlıştır?', 'I', ['II', 'III', 'IV'], '"ne yazık ki" üç ayrı sözcükten oluşur; içindeki "ki" bağlacı da ayrı yazılır.'),
  ('Hasta yatağından kalkınca Allah\'a şükür etti (I), ardından doktora teşekkür etti (II), hemşireden özür diledi (III) ve taburcu olmak için başvurdu (IV). Bu cümlede numaralanmış yerlerden hangisinde birleşik fiil yanlış yazılmıştır?', 'I', ['II', 'III', 'IV'], '"şükür" sözcüğü "etmek" ile birleşirken ünlü düşmesine uğrar ve birleşik fiil bitişik yazılır: şükretti.'),
  ('Aşağıdaki cümlelerin hangisinde ara yön adı yanlış yazılmıştır?', 'Rüzgâr bütün gün güney batıdan esti.', ['Fırtınanın kuzeydoğudan geleceği açıklandı.', 'Kentin güneydoğusunda yeni bir park yapıldı.', 'Göçmen kuşlar sonbaharda kuzeybatıdan gelir.'], 'Ara yön adları iki yön adının birleşmesiyle oluşan birleşik sözcüklerdir ve bitişik yazılır: güneybatı.'),
  ('Kocaeli Yarımadası (I) üzerine yapılan çalışmada eskiden kalma bir dairenin yarı çapı (II) ölçüldü; dikdörtgen (III) biçimli alan da eşkenar (IV) üçgenlere bölündü. Bu cümlede numaralanmış sözlerden hangisinin yazımı yanlıştır?', 'II', ['I', 'III', 'IV'], 'Geometride kullanılan "yarıçap" birleşik bir terimdir ve bitişik yazılır; "yarımada, dikdörtgen, eşkenar" da bitişiktir.'),
  ('Aşağıdaki cümlelerin hangisinde bir deniz canlısının adı yanlış yazılmıştır?', 'Kumsalda beş kollu bir deniz yıldızı bulduk.', ['Akvaryumda renkli balıklar yüzüyordu.', 'Kıyıdaki kayaların üstü baştan sona siyah midyelerle kaplıydı.', 'Balıkçılar ağlarıyla kalamar avlıyordu.'], 'Anlam kaymasıyla bir canlıya ad olan "denizyıldızı" bitişik yazılır.'),
  ('"Bir konu hakkında yeterli bilgi edinmeden önceden oluşturulan olumsuz kanı" anlamındaki sözcüğün doğru yazımı hangisidir?', 'önyargı', ['ön yargı', 'ön-yargı', 'önyarğı'], '"önyargı" yazım kılavuzunda bitişik yazılan birleşik bir addır.'),
  ('Herkesin kendi hakını (I) araması doğaldır; ancak başkalarının (II) emeğine saygı (III) göstermeyi de unutmamalıyız (IV). Bu cümlede numaralanmış sözcüklerden hangisinin yazımı yanlıştır?', 'I', ['II', 'III', 'IV'], '"hak" sözcüğü ünlüyle başlayan ek aldığında sondaki ünsüz ikizleşir ve bu yazıda gösterilir: hakkını.'),
  ('"Babam 1990 ... yıllarda bu kente taşınmış." cümlesinde boşluğa getirilecek ekin yazımı aşağıdakilerin hangisinde doğrudur?', '1990\'lı', ['1990\'li', '1990lı', '1990\'lu'], 'Rakamla yazılan sayıya gelen ek kesmeyle ayrılır ve sayının okunuşuna uyar: "bin dokuz yüz doksanlı".'),
  ('Kesir sayılarının harfle yazılışıyla ilgili aşağıdaki cümlelerin hangisinde yazım doğrudur?', 'Pastanın dörtte üçü ilk gün yenmişti.', ['Pastanın dörtteüçü ilk gün yenmişti.', 'Pastanın dörde üçü ilk gün yenmişti.', 'Pastanın dört\'te üçü ilk gün yenmişti.'], 'Kesir sayıları harfle yazılırken her sayı ayrı yazılır: dörtte üç.'),
  ('Para tutarlarının rakamla yazılışıyla ilgili aşağıdakilerden hangisi doğrudur?', '1.250,50 TL', ['1,250.50 TL', '1250.50 TL', '1.250.50 TL'], 'Türkçede büyük sayılarda basamak grupları nokta ile, ondalık kısım ise virgülle ayrılır.'),
  ('Aşağıdaki cümlelerin hangisinde "demek" fiilinin çekiminde yazım yanlışı yapılmıştır?', 'Öğretmenimiz ne deyorsa ona dikkat edin.', ['Herkes bu konuda farklı bir şey diyor.', 'Ona ne diyeceğimi bilemedim.', 'Annem bize her zaman "Dikkatli olun." der.'], '"demek" fiili "-yor" ya da "-ecek" aldığında kök ünlüsü daralır ve "i" ile yazılır: diyor, diyecek.'),
  ('Aşağıdaki cümlelerin hangisinde ek-fiil "-dir" yanlış yazılmıştır?', 'En sevdiğim mevsim ilkbahar\'dır.', ['Türkiye\'nin başkenti Ankara\'dır.', 'Bugün günlerden pazartesidir ve okullar açıktır.', 'Bu çantanın sahibi Selin\'dir.'], 'Ek-fiil cins adlara bitişik ve kesmesiz yazılır: ilkbahardır. Kesme yalnız özel adlardan sonra kullanılır.'),
  ('Tarih dersinde İlk çağ (I) uygarlıklarından sonra Orta Çağ\'a (II) geçtik; öğretmenimiz (III) Yeni Çağ\'ın (IV) başlangıcını gelecek hafta anlatacak. Numaralanmış sözlerden hangisi yazım kurallarına uymamaktadır?', 'I', ['II', 'III', 'IV'], 'Tarih çağlarının adları özel ad sayılır ve her sözcüğü büyük harfle yazılır: İlk Çağ.'),
  ('Dostoyevski\'nin (I) "Suç Ve Ceza" (II) adlı romanını okuduktan sonra yazarın (III) öbür eserlerini de (IV) merak ettim. Bu cümledeki numaralanmış sözlerden hangisi düzeltilmelidir?', 'II', ['I', 'III', 'IV'], 'Eser adlarında her sözcük büyük harfle başlar; ancak adın içindeki "ve" bağlacı küçük yazılır: "Suç ve Ceza".'),
  ('Törene katılan binbaşı (I) lacivert takımının üzerine kırmızı bir boyun bağı (II) takmış, yanındaki yüzbaşı (III) ise üniformasını (IV) giymişti. Bu cümlede numaralanmış sözlerden hangisinin yazımı yanlıştır?', 'II', ['I', 'III', 'IV'], 'Kravat anlamındaki "boyunbağı" anlam kaymasıyla oluşmuş birleşik sözcüktür ve bitişik yazılır.'),
  ('Soğuk havada kapüşonlu (I) montunu giyen kardeşim, şarküteriden (II) aldığı peynirleri bir kavonoza (III) koyup buzdolabına (IV) yerleştirdi. Bu cümledeki numaralanmış sözlerden hangisi düzeltilmelidir?', 'III', ['I', 'II', 'IV'], 'Sözcüğün doğru yazımı "kavanoz"dur.'),
  ('Raporun ekindeki döküman (I) incelendiğinde, araştırmada kullanılan yöntemin (II) güvenilir (III) olduğu anlaşıldı (IV). Numaralı sözlerin hangisinde yazım yanlışı yapılmıştır?', 'I', ['II', 'III', 'IV'], 'Fransızca kökenli sözcüğün yazım kılavuzundaki biçimi "doküman"dır.'),
  ('Ağabeyim (I) her sabah spor salonunda ağırlık eksersizi (II) yapıyor, sonra (III) duş alıp işine (IV) gidiyor. Numaralanmış sözlerden hangisi yazım kurallarına uymamaktadır?', 'II', ['I', 'III', 'IV'], 'Fransızca kökenli sözcük "egzersiz" biçiminde yazılır.'),
  ('Ödevim için atasözü (I) ve özdeyiş (II) toplamak amacıyla kitap evine (III) gittim; satıcı bana birkaç (IV) sözlük önerdi. Numaralı sözlerin hangisinde yazım yanlışı yapılmıştır?', 'III', ['I', 'II', 'IV'], 'Kitap satılan dükkânı anlatan "kitabevi" kalıplaşmış birleşik sözcüktür; birleşirken yumuşama olur ve bitişik yazılır.'),
  ('Ablamın doğumgünü (I) için hazırladığımız sürpriz (II) partide herkes (III) çok eğlendi; hediyelerini (IV) açınca ablam çok duygulandı. Bu cümlede numaralanmış sözlerden hangisinin yazımı yanlıştır?', 'I', ['II', 'III', 'IV'], '"doğum günü" kendi anlamını koruyan iki sözcükten oluşan bir ad tamlamasıdır ve ayrı yazılır.'),
  ('Kardeşim yağmurda ıslanmasın diye kapşonunu (I) başına geçirdi (II), çantasını (III) da montunun altına sakladı (IV). Numaralanmış sözlerden hangisi yazım kurallarına uymamaktadır?', 'I', ['II', 'III', 'IV'], 'Fransızca kökenli sözcüğün yazım kılavuzundaki biçimi "kapüşon"dur.'),
  ('Aşağıdaki cümlelerin hangisinde virgül, aynı adı niteleyen eş görevli sıfatları ayırmak için kullanılmıştır?', 'Uzun, ince bir yoldan geçerek köye vardık.', ['Ali, bu akşam bize gelecek misin?', 'Sabah kalktı, kahvaltısını yaptı, çıktı.', 'Evet, bu kitabı ben de okudum.'], '"uzun" ve "ince" sözcüklerinin ikisi de "yol" adını niteler; eş görevli sıfatlar virgülle ayrılır.'),
  ('"ka-lem-lik" yazımında kısa çizgi hangi amaçla kullanılmıştır?', 'Sözcüğün hecelerini göstermek için', ['Sözcüğün kökünü ve eklerini ayırmak için', 'İki yer adı arasındaki ilişkiyi göstermek için', 'Satır sonunda sözcüğü bölmek için'], 'Dil bilgisi çalışmalarında bir sözcüğün heceleri kısa çizgiyle ayrılarak gösterilir. "kalem-lik" biçimindeki ayırma ise kök ve eki gösterirdi.'),
  ('"Otoyolda azami hız 120 km/sa olarak belirlenmiştir." cümlesinde eğik çizgi hangi anlamı karşılamaktadır?', '"başına, her biri için" anlamını', ['"ve" ya da "veya" anlamını', '"ile arasında" anlamını', '"yaklaşık olarak" anlamını'], 'Ölçü birimlerinde eğik çizgi bölme ya da oran bildirir: km/sa, "saatte kilometre" yani bir saatte alınan yol demektir.'),
  ('Aşağıdakilerin hangisinde soru işareti, cümlenin sonunda değil, cümlenin içindeki bir bilginin kesin olmadığını belirtmek için kullanılmıştır?', 'Bu han, Selçuklular döneminde (1229?) yaptırılmıştır.', ['Bu hanı kim yaptırmış, bilen var mı?', 'Han kaç yılında yapılmış?', 'Sence bu han ne kadar eski?'], 'Ayraç içinde kullanılan soru işareti, kendisinden önceki bilginin kesin olmadığını, şüpheyle verildiğini gösterir.'),
  ('Bir öğrencinin yemek tarifi ödevinde geçen aşağıdaki sebze adlarından hangisi yanlış yazılmıştır?', 'ispanak', ['kereviz', 'enginar', 'pırasa'], 'Yazım kılavuzunda bu sebzenin adı "ıspanak" biçimindedir.'),
  ('Bir sağlık broşüründe geçen aşağıdaki tıbbi araç adlarından hangisi yanlış yazılmıştır?', 'steteskop', ['termometre', 'röntgen', 'tansiyon aleti'], 'Doktorların kalp ve akciğer seslerini dinlediği aletin adı "stetoskop" biçiminde yazılır.'),
  ('Spor dallarının adlarını sıralayan aşağıdaki sözcüklerden hangisi yanlış yazılmıştır?', 'cimnastik', ['hentbol', 'badminton', 'maraton'], 'Bu spor dalının adı yazım kılavuzunda "jimnastik" biçimindedir.'),
  ('Ses düzenlerinde kullanılan, elektrik sinyalini sese dönüştüren aygıtın adı nasıl yazılır?', 'hoparlör', ['hoperlör', 'hoparlor', 'hopparlör'], 'Fransızca kökenli sözcüğün doğru yazımı "hoparlör"dür.'),
  ('Bir resmî kuruma yazılan dilekçede geçen aşağıdaki sözcüklerden hangisi yanlış yazılmıştır?', 'müracat', ['tutanak', 'genelge', 'yönetmelik'], 'Arapça kökenli "başvuru" anlamındaki sözcük iki "a" ile yazılır: müracaat.'),
  ('Hava durumu ve iklimle ilgili aşağıdaki sözcüklerden hangisi yanlış yazılmıştır?', 'meteroloji', ['termometre', 'hava basıncı', 'soğuk cephe'], 'Hava olaylarını inceleyen bilimin adı "meteoroloji" biçiminde yazılır.'),
  ('Bir beslenme rehberinde geçen aşağıdaki sözcüklerden hangisinin yazımı yanlıştır?', 'kalesterol', ['protein', 'karbonhidrat', 'vitamin'], 'Kanda bulunan yağ benzeri maddenin adı "kolesterol" biçiminde yazılır.'),
  ('Meslek adlarının sıralandığı aşağıdaki sözcüklerden hangisinin yazımı yanlıştır?', 'aşcı', ['eczacı', 'kuyumcu', 'sütçü'], '"ş" sert ünsüzüyle biten sözcüğe gelen "-cı" eki benzeşmeyle "-çı" olur: aşçı.'),
  ('Miktar bildiren belgisiz sözler düşünüldüğünde aşağıdaki cümlelerin hangisinde yazım yanlışı vardır?', 'Bu konuda pekçok kitap okudum ama aradığımı bulamadım.', ['Sınavdan önce kütüphanede birlikte birçok deneme sınavı çözdük.', 'Toplantıya birkaç kişi gelmedi.', 'Bu ay birtakım değişiklikler yapılacak.'], '"pek çok" iki ayrı sözcükten oluşur ve ayrı yazılır.'),
  ('Taziye ziyaretinde söylenen dilek sözüyle ilgili olarak aşağıdaki cümlelerin hangisinde yazım doğrudur?', 'Cenaze töreninde aileye başsağlığı diledik.', ['Cenaze töreninde aileye baş sağlığı diledik.', 'Cenaze töreninde aileye baş-sağlığı diledik.', 'Cenaze töreninde aileye başsağlıgı diledik.'], 'Ölenin yakınlarına iletilen "başsağlığı" kalıplaşmış birleşik addır ve bitişik yazılır.'),
  ('Edebiyat dersinde anlatılan düzyazı türlerini sayan aşağıdaki sözcüklerden hangisi yazım kılavuzuna uygun değildir?', 'hikaye', ['roman', 'deneme', 'makale'], 'Yazım kılavuzunda bu sözcük, "k" ünsüzünün ince okunduğunu göstermek için düzeltme işaretiyle yazılır: hikâye.'),
  ('Bir işin yürütülmesinde izlenen resmî yol ve yöntemleri anlatan Fransızca kökenli sözcüğün doğru yazımı hangisidir?', 'prosedür', ['prosüdür', 'prosedur', 'porsedür'], 'Sözcüğün yazım kılavuzundaki biçimi "prosedür"dür.'),
  ('Sonbaharda açan, çok yapraklı çiçeğiyle bilinen bitkinin adı aşağıdakilerin hangisinde doğru yazılmıştır?', 'kasımpatı', ['kasım patı', 'kasımpat', 'kasım-patı'], 'Bitki adı olarak anlam kayması taşıyan "kasımpatı" bitişik ve küçük harfle yazılır.'),
  ('Annem alışverişten dönünce sütü ve yumurtaları buz dolabına (I) koydu, ekmekleri (II) ekmek dolabına (III) yerleştirdi, sebzeleri de tezgâha (IV) bıraktı. Bu cümlede numaralanmış sözlerden hangisinin yazımı yanlıştır?', 'I', ['II', 'III', 'IV'], 'Yazım kılavuzunda soğutucu aygıtın adı bitişik yazılır: buzdolabı.'),
  ('Kış aylarında kuşburnu (I) çayı içen dedem, bahçesindeki keçi boynuzu (II) ağacının meyvelerini de toplar, turnagagası (III) çiçeklerini sular, sonra kahvaltısını (IV) yapardı. Bu cümlede numaralanmış sözlerden hangisinin yazımı yanlıştır?', 'II', ['I', 'III', 'IV'], 'Bitki adları anlam kaymasıyla oluşmuşsa bitişik yazılır: keçiboynuzu.'),
  ('Türkiye\'deki illerden söz eden aşağıdaki cümlelerin hangisinde birleşik yer adı kurala aykırı yazılmıştır?', 'Afyon Karahisar kaymağı ve sucuğuyla tanınır.', ['Şanlıurfa\'nın Balıklıgöl\'ü çok ünlüdür.', 'Çanakkale Boğazı Ege\'yi Marmara\'ya bağlar.', 'Kahramanmaraş\'ta dövülerek yapılan dondurma çok sevilir.'], 'Birden çok sözcükten oluşan yerleşim yeri adları bitişik yazılır: Afyonkarahisar.'),
  ('"Kitap bende kaldı." ve "Ben de bu kitabı okudum." cümlelerindeki "de" ile ilgili aşağıdakilerden hangisi doğrudur?', 'İlkinde bulunma eki, ikincisinde bağlaçtır.', ['İkisi de kalma yeri bildiren bulunma ekidir.', 'İkisi de bağlaçtır.', 'İlkinde bağlaç, ikincisinde bulunma ekidir.'], '"bende" sözcüğünde "-de" kalma yerini bildirir ve bitişik yazılır. "ben de" sözündeki "de" ise "dahi" anlamı katan bağlaçtır ve ayrı yazılır.'),
  ('Aşağıdaki cümlelerin hangisinde "ki" yanlış yazılmıştır?', 'Öyleki herkes onun sözlerini dikkatle dinledi.', ['Bilmem ki bu karmaşık sorunu nasıl çözeceğiz.', 'Sanki bütün dünya onun etrafında dönüyordu.', 'Belki yarın görüşürüz.'], '"öyle ki" sözündeki "ki" bağlaçtır ve ayrı yazılır. "sanki, belki" ise kalıplaşmış sözcüklerdir.'),
  ('Soru eki "mi"ye ek-fiil getirildiğinde aşağıdakilerin hangisinde yazım doğrudur?', 'Bu söylenenler gerçek midir?', ['Bu söylenenler gerçekmidir?', 'Bu söylenenler gerçek mi dir?', 'Bu söylenenler gerçek mi\'dir?'], 'Soru eki "mi" ayrı yazılır, ondan sonra gelen ek-fiil ise "mi"ye bitişik yazılır: gerçek midir.'),
  ('Müdür Bey kapıyı çalan öğrenciye "Müsade (I) edersen önce şu yazıyı (II) bitireyim, sonra seninle (III) konuşuruz (IV)." dedi. Bu cümlede numaralanmış sözlerden hangisinin yazımı yanlıştır?', 'I', ['II', 'III', 'IV'], '"izin" anlamındaki Arapça kökenli sözcük iki "a" ile yazılır: müsaade.'),
  ('Bir kurumda belirli bir iş ya da öğrenci grubu için ayrılan sınırlı sayıdaki yeri anlatan sözcük nasıl yazılır?', 'kontenjan', ['kontejan', 'kontenjen', 'kotenjan'], 'Fransızca kökenli sözcüğün yazım kılavuzundaki biçimi "kontenjan"dır.'),
  ('Tanışma sırasında verilen, kişinin adını ve iletişim bilgilerini taşıyan küçük kartın adı aşağıdakilerin hangisinde doğru yazılmıştır?', 'kartvizit', ['kardvizit', 'kartivizit', 'kartvizid'], 'Fransızca kökenli sözcük "kartvizit" biçiminde yazılır.'),
  ('Uzak ve yabancı ülkelere özgü, alışılmamış anlamındaki sözcüğün doğru yazımı aşağıdakilerden hangisidir?', 'egzotik', ['eksotik', 'egzotık', 'egzottik'], 'Fransızca kökenli sözcük "egzotik" biçiminde yazılır.'),
  ('Tanıtım amacıyla ücretsiz dağıtılan küçük ürün örneği anlamındaki sözcük aşağıdakilerin hangisinde doğru yazılmıştır?', 'eşantiyon', ['eşantion', 'eşantiyön', 'eşhantiyon'], 'Fransızca kökenli sözcüğün doğru yazımı "eşantiyon"dur.'),
  ('Aşağıdaki cümlelerin hangisinde belirli bir gün adının yazımı yanlıştır?', 'Her yıl mayıs ayının ikinci pazarı anneler günü olarak kutlanır.', ['24 Kasım Öğretmenler Günü okulumuzda coşkuyla kutlandı.', 'Dünya Çevre Günü dolayısıyla okul bahçesine fidan diktik.', 'Babalar Günü yaklaşırken babama yeni bir kol saati aldım.'], 'Belirli gün ve hafta adları özel ad sayılır, her sözcüğü büyük harfle başlar: Anneler Günü.'),
  ('Okul derslerinin adlarını sıralayan aşağıdaki cümlelerin hangisinde yazım doğrudur?', 'Çarşamba günü beden eğitimi ve görsel sanatlar dersimiz var.', ['Çarşamba günü bedeneğitimi ve görsel sanatlar dersimiz var.', 'Çarşamba günü beden eğitimi ve görselsanatlar dersimiz var.', 'Çarşamba günü bedeneğitimi ve görselsanatlar derslerimiz vardı.'], 'Ders adlarını oluşturan bu söz öbekleri kendi anlamını koruyan sıfat ve ad tamlamalarıdır, ayrı yazılır.'),
  ('Kuru meyvelerin şekerli suda pişirilmesiyle yapılan içeceğin adı nasıl yazılır?', 'hoşaf', ['hoşap', 'hoşhaf', 'hoşav'], 'Farsça kökenli sözcük "hoşaf" biçiminde yazılır.'),
  ('Saygı bildiren bir davranışla "büyüğün sözünü dinleyip ona uyma" anlamındaki sözcük aşağıdakilerin hangisinde doğru yazılmıştır?', 'itaat', ['itat', 'itaad', 'itaatt'], 'Arapça kökenli sözcük iki "a" ile yazılır: itaat.'),
  ('"Sevgili öğrenciler ( ) yarın derse gelirken yanınızda şunlar olsun ( ) kalem, defter ve silgi ( )" cümlesinde ayraçlarla gösterilen yerlere sırasıyla hangi işaretler getirilmelidir?', 'virgül, iki nokta, nokta', ['iki nokta, virgül, nokta', 'virgül, noktalı virgül, üç nokta', 'ünlem, virgül, nokta'], 'Hitaptan sonra virgül, açıklama yapılacak cümlenin sonunda iki nokta, cümle bitince nokta kullanılır.'),
  ('"Hey ( ) içeride kimse yok mu ( )" cümlesinde ayraçlarla gösterilen yerlere sırasıyla hangi işaretler gelmelidir?', 'virgül, soru işareti', ['soru işareti, ünlem', 'nokta, soru işareti', 'iki nokta, ünlem'], 'Cümle başındaki ünlemden sonra cümle küçük harfle sürdüğü için virgül konur; soru bildiren cümlenin sonuna soru işareti gelir.'),
  ('"TBMM( )nin açılış tarihi 23 Nisan 1920( )dir." cümlesinde ayraçlarla gösterilen yerlere sırasıyla hangi işaretler getirilmelidir?', 'kesme, kesme', ['kesme, kısa çizgi', 'kısa çizgi, kesme', 'nokta, kesme'], 'Kısaltmalara ve rakamla yazılmış sayılara getirilen ekler kesme işaretiyle ayrılır: TBMM\'nin, 1920\'dir.'),
  ('"Evet ( ) dedi ( ) bu vazoyu ben kırdım ( )" cümlesinde ayraçlarla gösterilen yerlere sırasıyla hangi işaretler getirilmelidir?', 'virgül, virgül, nokta', ['iki nokta, virgül, nokta', 'virgül, iki nokta, ünlem', 'nokta, virgül, üç nokta'], '"Evet" sözünden sonra virgül, araya giren "dedi" sözünden sonra yine virgül konur; cümle noktayla biter.'),
  ('"Ali ( ) Ayşe ve Selin ( ) yarın sabah ( ) erkenden yola çıkacaklar." cümlesinde ayraçlarla gösterilen yerlerden hangisine virgül konmalıdır?', 'Yalnız birincisine', ['Yalnız ikincisine', 'Birincisine ve üçüncüsüne', 'Üçüne de'], 'Eş görevli sözcükler (Ali, Ayşe) virgülle ayrılır. Özne ile yüklem arasına ve zarflardan sonra gereksiz yere virgül konmaz.'),
  ('Kesme işaretinin görevleri düşünüldüğünde aşağıdaki cümlelerden hangisi kullanım amacı bakımından öbürlerinden ayrılır?', 'Dedem iç çekerek "N\'apalım, kısmet değilmiş." dedi.', ['Toplantı yarın İzmir\'de yapılacak.', 'Kardeşim Selin\'e bir kitap aldım.', 'Bu yıl teyzemler İstanbul\'dan Ankara\'ya taşındılar.'], 'Öbür cümlelerde kesme, özel adlara getirilen ekleri ayırır. "n\'olur" yazımında ise söyleyişte düşen bir sesin yerini gösterir.'),
  ('Aşağıdaki cümlelerin hangisinde iki nokta, kendisinden sonra açıklama yapılacağını göstermek için kullanılmamıştır?', 'AHMET: Bu saatte kim gelir ki?', ['Ona tek bir şey yeterdi: biraz sevgi.', 'Çantasında üç şey vardı: kitap, kalem, defter.', 'Babamın bir tutkusu vardı: balık tutmak.'], 'Öbür cümlelerde iki noktadan sonra açıklama ya da örnek gelir. Konuşma metninde ise iki nokta, konuşanın adını sözünden ayırır.'),
  ('Aşağıdaki cümlelerin hangisinde noktalı virgül yanlış kullanılmıştır?', 'Kardeşim; sabah erkenden okula gitti.', ['Sabah erkenden kalktı; ama okula yine geç kaldı.', 'Tatlılardan baklava, kadayıf; çorbalardan ezogelin, mercimek seçildi.', 'Yorgundu; çünkü bütün gece çalışmıştı.'], 'Noktalı virgül, cümleleri ya da kendi içinde virgül bulunan öbekleri ayırır. Özne ile yüklem arasına noktalı virgül konmaz.'),
  ('Ünlüyle başlayan ek aldığında ikinci hecesindeki ünlüyü yitiren sözcükler düşünüldüğünde aşağıdaki cümlelerin hangisinde yazım yanlışı vardır?', 'Kafasına gelen her fikiri hemen deftere yazardı.', ['Ağzını açmadan, sessizce anlatılanları sonuna kadar dinledi.', 'Gönlü kırılmasın diye susmuş.', 'Burnunun ucunu göremeyecek kadar karanlıktı.'], '"fikir" sözcüğü ünlüyle başlayan ek aldığında ikinci hecedeki ünlü düşer: fikri.'),
  ('Bilimsel yayınlarda birden çok yazarlı bir esere atıf yapılırken kullanılan "vd." kısaltmasının açılımı hangisidir?', 've diğerleri', ['ve devamı', 've daha', 'vesaire diğer'], '"vd." kısaltması "ve diğerleri" anlamında kullanılır.'),
  ('Halk şiirinde geçen "Yâr yüzünü göremedim" dizesinde "yâr" sözcüğünün düzeltme işaretiyle yazılmasının nedeni nedir?', '"uçurum" anlamındaki "yar" sözcüğüyle karışmasını önlemek', ['Sözcüğün Türkçe kökenli olduğunu göstermek', 'Sözcüğün yabancı kökenli bir özel ad olduğunu göstermek', 'Sözcüğün sonuna Arapça kökenli bir nispet eki geldiğini belirtmek'], '"sevgili" anlamındaki "yâr", yazılışı aynı olan "yar" (uçurum) sözcüğünden ayırt edilmek için düzeltme işaretiyle yazılır.'),
  ('"olanak" anlamındaki Arapça kökenli sözcük yazım kılavuzuna göre hangisindeki gibi yazılır?', 'imkân', ['imkan\'', 'imkahn', 'immkân'], '"k" ünsüzünün ince okunduğunu göstermek için sözcük düzeltme işaretiyle yazılır: imkân.'),
  ('Aşağıdaki cümlelerin hangisinde soru bildiren bir söz yanlışlıkla bitişik yazılmıştır?', 'Seninle nezaman buluşacağımızı bilmiyorum.', ['Bu kadar yolu nasıl yürüdün?', 'Niçin bu kadar geç kaldın?', 'Bu proje için tam olarak ne kadar para gerekiyor?'], '"ne zaman" iki ayrı sözcükten oluşur ve ayrı yazılır. "nasıl, niçin" ise kalıplaşarak tek sözcük olmuştur.'),
  ('Limanları dalgalardan korumak için denize yapılan set aşağıdakilerin hangisindeki gibi yazılır?', 'dalgakıran', ['dalga kıran', 'dalga-kıran', 'dalgakıranı\''], 'Bu birleşik ad anlam bütünlüğü kazandığı için bitişik yazılır.'),
  ('Hava saldırılarına karşı kullanılan topun adı aşağıdakilerin hangisinde doğru yazılmıştır?', 'uçaksavar', ['uçak savar', 'uçak-savar', 'uçaksavarı\''], 'Bir silahı adlandıran bu birleşik sözcük bitişik yazılır.'),
  ('Mahkemede uzmanlığına başvurulan ve görüşü alınan kişiyi anlatan sözcüğün doğru yazımı hangisidir?', 'bilirkişi', ['bilir kişi', 'bilir-kişi', 'bilirkişiı'], '"bilirkişi" kalıplaşmış birleşik sözcüktür ve bitişik yazılır.'),
  ('Aşağıdakilerden hangisi zaman bildiren ve ayrı yazılması gereken bir sözdür?', 'ilk önce', ['bugün', 'birdenbire', 'yarın'], '"ilk önce" iki ayrı sözcükten oluşur ve ayrı yazılır. "bugün" ve "birdenbire" ise bitişik yazılan kalıplaşmış sözcüklerdir.'),
  ('Toplantıya en az (I) yirmi kişinin katılması gerekiyordu; kimizaman (II) bu sayıya ulaşılamıyor, o zaman (III) da toplantı başka bir güne (IV) ertelenmek zorunda kalınıyordu. Bu cümlede numaralanmış sözlerden hangisinin yazımı yanlıştır?', 'II', ['I', 'III', 'IV'], '"kimi zaman" iki ayrı sözcükten oluşur ve ayrı yazılır.'),
  ('Aşağıdaki cümlelerin hangisinde yabancı kökenli bir sözcük yanlış yazılmıştır?', 'Eski evin bahçeye bakan geniş bir verendası vardı.', ['Salonun ortasına kristal bir avize asılmıştı.', 'Odanın köşesinde eski bir şömine duruyordu.', 'Pencerelerde dantel perdeler vardı.'], 'Evlerin önündeki üstü örtülü açık bölümün adı "veranda" biçiminde yazılır.'),
  ('(I) Kargo şirketi paketin yolda olduğunu bildirdi. (II) Ancak teslimat bir hafta gecikti. (III) Müşteri, ürünün biran önce gönderilmesini istedi. (IV) Şirket bunun için özür diledi. Bu parçada numaralanmış cümlelerin hangisinde yazım yanlışı vardır?', 'III', ['I', 'II', 'IV'], '"bir an önce" üç ayrı sözcükten oluşur ve ayrı yazılır.'),
  ('(I) Turnuvanın ilk maçını kaybettik. (II) Antrenörümüz bizi soyunma odasında topladı. (III) "Birdahaki maçta daha dikkatli olacağız." dedi. (IV) Hepimiz başımızı sallayarak onu onayladık. Bu parçada numaralanmış cümlelerin hangisinde yazım yanlışı vardır?', 'III', ['I', 'II', 'IV'], '"bir dahaki" iki ayrı sözcükten oluşur ve ayrı yazılır.'),
  ('(I) Telefonla arayan arkadaşım nerede olduğumu sordu. (II) "Şuan kütüphanedeyim, birazdan çıkarım." dedim. (III) Yarım saat sonra kapıda buluştuk. (IV) Birlikte sinemaya gittik. Bu parçada numaralanmış cümlelerin hangisinde yazım yanlışı vardır?', 'II', ['I', 'III', 'IV'], '"şu an" iki ayrı sözcükten oluşur ve ayrı yazılır.'),
  ('(I) Maç başladığında stadyum nerdeyse doluydu. (II) Taraftarlar takımlarını coşkuyla destekledi. (III) İlk yarı golsüz bitti. (IV) İkinci yarıda ev sahibi takım iki gol attı. Bu parçada numaralanmış cümlelerin hangisinde yazım yanlışı vardır?', 'I', ['II', 'III', 'IV'], 'Yazı dilinde "neredeyse" biçimi kullanılır; konuşma dilindeki kısalmış söyleyiş yazıya geçirilmez.'),
  ('(I) Yağmur yüzünden piknik iptal oldu. (II) Hiçolmazsa evde bir film izleyelim, dedi kardeşim. (III) Patlamış mısır hazırlayıp salona geçtik. (IV) Akşamı çok keyifli geçirdik. Bu parçada numaralanmış cümlelerin hangisinde yazım yanlışı vardır?', 'II', ['I', 'III', 'IV'], '"hiç olmazsa" iki ayrı sözcükten oluşur ve ayrı yazılır.'),
  ('Selin tatilde yazdığı kartpostalı göndermeden önce yazım yanlışlarını denetledi. Kartpostaldaki aşağıdaki cümlelerden hangisi yazım kurallarına tümüyle uygundur?', 'Bodrum\'da hava her gün güneşli.', ['Sabahları denizde yüzüp öğlenleri kumsalda kitap okuyorum, herşey çok güzel.', 'Akşamları Kalenin çevresinde yürüyüş yapıyoruz.', 'Yarın tekne turuna çıkacağız, inşallah havada güzel olur.'], '"herşey" ayrı, "Kale" sözcüğü cins ad olarak küçük ya da tam adla yazılmalı, bağlaç olan "de" ise ayrı yazılmalıdır (hava da).'),
  ('Bir öğrencinin kompozisyon ödevinden alınan aşağıdaki cümlelerden hangisi öğretmeni tarafından yazım yanlışı içermediği için işaretlenmemiştir?', 'Okulumuzun bahçesinde yaşlı bir çınar ağacı var.', ['Bu ağacın gölgesinde teneffüsde dinleniriz.', 'Ağacın gövdesine kimbilir kaç kişi adını kazımış.', 'Dedem bu ağacın yüz yıllık olduğunu söyler, bende ona inanırım.'], '"teneffüste", "kim bilir" ve bağlaç olan "ben de" biçimleri doğrudur; öbür seçeneklerde bu yanlışlar vardır.'),
  ('Kerem, sınıf panosuna asılacak gezi duyurusunu yazarken bir cümleyi hatasız yazdı. Bu cümle aşağıdakilerden hangisidir?', 'Gezimiz sabah 08.30\'da okul önünden başlayacaktır.', ['Öğrenciler yanlarında öğle yemeği ve su getirmelidir, Ayrıca rahat ayakkabı giyilmelidir.', 'Gezi sırasında Anıtkabir ve Etnografya müzesi ziyaret edilecektir.', 'Veli izin belgesinin en geç perşembe günü teslim edilmesi gerekmektedir..'], 'Virgülden sonra gelen sözcük büyük harfle başlamaz; müze adındaki tür adı adın parçası olduğundan büyük yazılır (Etnografya Müzesi); cümle sonunda tek nokta kullanılır.'),
  ('Bir spor kulübünün internet sayfasındaki haberden alınan cümlelerin yalnız biri yazım kurallarına uygundur. Bu cümle hangisidir?', 'Takımımız sezonu ikinci sırada tamamladı.', ['Sezonun son maçında rakibimizi 3-1 yendik, Taraftarlarımız sahayı doldurdu.', 'Teknik direktörümüz yeni sezon için antreman programını açıkladı.', 'Kaptanımız Mert, yılın en iyi oyuncusu seçildi, ödülünü Pazartesi alacak.'], 'Virgülden sonra büyük harf kullanılmaz; doğru yazım "antrenman"dır; tarih bildirmeyen gün adı küçük yazılır.'),
  ('Doğa yürüyüşüne katılan bir grubun tuttuğu günlükten alınan cümlelerden hangisi yazım bakımından kusursuzdur?', 'Kaz Dağları\'nın eteklerinde kamp kurduk.', ['Sabah erkenden kalkıp şelaleye doğru yürüdük, yol boyunca birsürü kuş gördük.', 'Rehberimiz, bu bölgede ki bitkilerin çoğunun şifalı olduğunu anlattı.', 'Akşam kamp ateşinin başında Türküler söyleyip sohbet ettik.'], '"bir sürü" ayrı yazılır; sıfat yapan "-ki" bitişik yazılır (bölgedeki); "türkü" cins addır, küçük harfle yazılır.'),
  ('Bir müzenin tanıtım broşüründen alınan aşağıdaki cümlelerden hangisinde yazım yanlışı yoktur?', 'Müzemiz salı günleri kapalıdır.', ['Müzede Osmanlı dönemine ait eşyalar, el yazması kitaplar ve hat örnekleri sergilenmektedir, Giriş ücretsizdir.', 'Rehberli turlar hergün saat 11.00\'de başlar.', 'Ziyaretçilerimizin müze içinde fotoğraf çekmemeleri rica olunur..'], 'Virgülden sonra büyük harf kullanılmaz; "her gün" ayrı yazılır; cümle sonunda tek nokta kullanılır.'),
  ('Elektrik kesildiğinde enerji sağlamak için kullanılan aygıtın adı nasıl yazılır?', 'jeneratör', ['jenaratör', 'jeneretör', 'jeneratörr'], 'Fransızca kökenli sözcüğün doğru yazımı "jeneratör"dür.'),
  ('Üyelerinin ortak çıkarı için kurulan ortaklık anlamındaki sözcük aşağıdakilerin hangisinde doğru yazılmıştır?', 'kooperatif', ['koperatif', 'kooparatif', 'koopperatif'], 'Sözcük yazım kılavuzunda iki "o" ile yazılır: kooperatif.'),
  ('Bir şeyin değerlendirilmesinde esas alınan ölçüt anlamındaki sözcüğün doğru yazımı hangisidir?', 'kriter', ['kıriter', 'kriterr', 'kiriter'], 'Söyleyişte "k" ile "r" arasına ünlü girse de yazıda gösterilmez: kriter.'),
  ('Belirli bir ölçüye, örneğe uygun olan; ölçün anlamındaki sözcük nasıl yazılır?', 'standart', ['standard', 'istandart', 'standartt'], 'Sözcüğün Türkçedeki yazımı "standart"tır; sondaki ünsüz "t" olarak yazılır.'),
  ('Maydanozun da kullanıldığı bir salata tarifini yazan öğrencinin aşağıdaki sözcüklerden hangisini yanlış yazdığı söylenebilir?', 'maydonoz', ['dereotu', 'taze soğan', 'nane'], 'Yazım kılavuzunda bu otun adı "maydanoz" biçimindedir.'),
  ('Öğretmenimiz yarışmada gösterdiğimiz başarıyı taktir (I) ettiğini söyledi; ardından bize birer kitap (II) hediye (III) etti ve hepimizi tebrik (IV) etti. Bu cümlede numaralanmış sözlerden hangisinin yazımı yanlıştır?', 'I', ['II', 'III', 'IV'], '"beğenme, değer verme" anlamındaki Arapça kökenli sözcük "takdir" biçiminde yazılır.'),
  ('Arapça kökenli olan ve "sağlık, esenlik" anlamına gelen sözcük nasıl yazılır?', 'sıhhat', ['sıhat', 'sıhhad', 'sıhhatt'], 'Sözcük iki "h" ile yazılır: sıhhat.'),
  ('Bu yıl uluslar arası (I) bir kongreye katılan hocamız, alışverişini (II) havalimanında (III) yapıp yurda (IV) döndü. Bu cümlede numaralanmış sözlerden hangisinin yazımı yanlıştır?', 'I', ['II', 'III', 'IV'], '"uluslararası" kalıplaşmış birleşik sıfattır ve bitişik yazılır; "alışveriş" ve "havalimanı" da bitişiktir.'),
  ('"Bir şeyi önceden sezme ve kestirme" anlamındaki sözcüğün yazım kılavuzundaki biçimi hangisidir?', 'öngörü', ['ön görü', 'ön-görü', 'öngörüler\''], '"öngörü" kalıplaşmış birleşik addır ve bitişik yazılır.'),
  ('Bir öğretmen "Okullar her yıl Eylül ayında açılır." cümlesindeki büyük harfin düzeltilmesini istiyor. Öğretmenin bu isteğinin gerekçesi aşağıdakilerden hangisidir?', 'Belirli bir tarih bildirmeyen ay adları küçük harfle başlar.', ['Ay adları hiçbir durumda büyük harfle yazılmaz.', 'Ay adı "ay" sözcüğüyle birlikte kullanılınca bitişik yazılır.', 'Ay adlarının büyük yazılması yalnızca cümle başında olur.'], 'Ay ve gün adları yalnızca belirli bir tarih bildirdiklerinde büyük harfle başlar (29 Ekim 1923); öbür durumlarda küçük yazılır: eylül ayında.'),
  ('İki öğrenci "hafta sonu" sözünün yazımını tartışıyor. Deniz bu sözün birleşik sözcük olduğu için bitişik yazılması gerektiğini, Arda ise ayrı yazılması gerektiğini savunuyor. Bu tartışmayla ilgili aşağıdakilerden hangisi doğrudur?', 'Arda haklıdır; söz yazım kılavuzunda ayrı yazılır.', ['Deniz haklıdır; zaman bildiren sözler bitişik yazılır.', 'İkisi de haklıdır; iki yazım da kabul edilir.', 'İkisi de haksızdır; söz kısa çizgiyle yazılır.'], 'Yazım kılavuzunda "hafta sonu" iki ayrı sözcük olarak yazılır.'),
  ('Bir öğrenci mektubunun başına "Hoşgeldin sevgili kuzenim," yazmıştır. Öğretmeninin bu yazıma ilişkin uyarısı aşağıdakilerden hangisi olmalıdır?', 'Karşılama sözü olan "hoş geldin" ayrı yazılmalıdır.', ['Hitaptan sonra virgül değil, ünlem kullanılmalıdır.', '"kuzenim" sözcüğü büyük harfle başlamalıdır.', 'Selamlama sözünden sonra virgül yerine iki nokta konmalıdır.'], '"hoş geldin" iki ayrı sözcükten oluşan bir kalıp sözdür ve ayrı yazılır.'),
  ('"İyiki gelmişsin, seni çok özlemiştim." cümlesindeki yazım yanlışı hangi gerekçeyle düzeltilmelidir?', '"ki" bağlacı kalıplaşmış sözcük oluşturmadığından ayrı yazılmalı.', ['"iyi" sözcüğü sıfat olduğu için kesmeyle ayrılmalıdır.', 'Cümle ünlem bildirdiği için sonuna ünlem konmalıdır.', '"gelmişsin" sözcüğü kişi ekinden ayrılarak "gelmiş sin" yazılmalıdır.'], '"iyi ki" sözündeki "ki" bağlaçtır ve ayrı yazılır; "belki, sanki" gibi kalıplaşmış bir sözcük değildir.'),
  ('"Çok çalıştı nevar ki sınavı kazanamadı." cümlesiyle ilgili olarak aşağıdaki değerlendirmelerden hangisi doğrudur?', '"ne var ki" üç ayrı sözcükle yazılmalıdır.', ['Cümlede yazım yanlışı yoktur.', '"çalıştı" sözcüğünden sonra iki nokta konmalıdır.', '"kazanamadı" sözcüğü ayrı yazılmalıdır.'], 'Karşıtlık bildiren "ne var ki" bağlacı üç ayrı sözcükten oluşur ve ayrı yazılır.'),
  ('Bir yazar, "Birbaşka zaman yine görüşürüz." cümlesindeki yazımın doğru olduğunu savunuyor. Bu yazımla ilgili hangisi söylenebilir?', 'Yanlıştır; "bir başka" ayrı yazılmalıdır.', ['Doğrudur; "birbaşka" kalıplaşmış bir belgisiz sıfattır.', 'Yanlıştır; "başka" sözcüğü büyük harfle başlamalıdır.', 'Doğrudur; "bir" ile kurulan bütün sözler bitişik yazılır.'], '"bir başka" söz öbeği kalıplaşmış bir sözcük oluşturmadığından ayrı yazılır.'),
  ('Bir öğrenci "Kardeşimin evdeki odası benim odamdan büyük." cümlesindeki "evdeki" sözcüğünü "evde ki" biçiminde düzeltmiştir. Bu düzeltmeyle ilgili aşağıdakilerden hangisi doğrudur?', 'Yanlıştır; sıfat yapan "-ki" eki bitişik yazılır.', ['Doğrudur; "ki" her zaman ayrı yazılır.', 'Doğrudur; bulunma ekinden sonra gelen "ki" bağlaçtır.', 'Yanlıştır; sözcük "ev\'deki" biçiminde yazılmalıdır.'], '"evdeki" sözcüğündeki "-ki" sıfat türeten bir ektir ve bitişik yazılır; ayrılması yanlışlığa yol açar.'),
  ('Ece "Ahmet Bey\'e" yazımında kesme işaretinin kişi adından hemen sonra konması gerektiğini, Mert ise kesmenin "Bey" sözcüğünden sonra konması gerektiğini düşünüyor. Hangi öğrencinin görüşü doğrudur?', 'Mert\'in; ek, saygı sözünden sonra kesmeyle ayrılır.', ['Ece\'nin; kesme her zaman kişi adından sonra gelir.', 'İkisinin de; iki yazım da kabul edilir.', 'İkisinin de değil; saygı sözlerine gelen ekler kesmesiz yazılır.'], 'Kişi adıyla birlikte kullanılan saygı sözü adın parçasıdır; ek bu bütünün sonuna kesmeyle getirilir: Ahmet Bey\'e.'),
  ('Bir ürünü ya da kurumu tanıtmak için hazırlanan küçük basılı kitapçığın adı nasıl yazılır?', 'broşür', ['bröşür', 'broşur', 'broşürr'], 'Fransızca kökenli sözcüğün doğru yazımı "broşür"dür.'),
  ('İki ya da daha çok kişi arasındaki karşılıklı konuşma anlamındaki sözcüğün yazım kılavuzundaki biçimi hangisidir?', 'diyalog', ['dialog', 'diyalok', 'diyaloğg'], 'Yazım kılavuzunda sözcük araya "y" girerek "diyalog" biçiminde yazılır.'),
  ('Tiyatroda oyuncuların rollerine uygun olarak giydikleri giysilerin adı nasıl yazılır?', 'kostüm', ['kostum', 'köstüm', 'kostümm'], 'Fransızca kökenli sözcüğün doğru yazımı "kostüm"dür.'),
  ('Radyo ve televizyon programlarının hazırlandığı ya da fotoğraf çekilen özel donanımlı yerin adı nasıl yazılır?', 'stüdyo', ['stüdyö', 'stüdiyo', 'sütüdyo'], 'İtalyanca kökenli sözcüğün yazım kılavuzundaki biçimi "stüdyo"dur.'),
  ('Doktorun müsayit (I) olduğu saatte randevu (II) alan hasta, bekleme salonunda (III) yarım saat oturdu (IV). Bu cümlede numaralanmış sözlerden hangisinin yazımı yanlıştır?', 'I', ['II', 'III', 'IV'], '"uygun, elverişli" anlamındaki Arapça kökenli sözcük "müsait" biçiminde yazılır.'),
  ('Tarladan elde edilen ürün anlamındaki Arapça kökenli sözcük aşağıdakilerin hangisinde doğru yazılmıştır?', 'mahsul', ['mahsül', 'mahsuul', 'mahzul'], 'Sözcüğün doğru yazımı "mahsul"dür.'),
  ('Kampa gitmeden önce ihtiyaclarımızı (I) bir listeye yazdık (II), alışverişi (III) de birlikte yaptık (IV). Bu cümlede numaralanmış sözlerden hangisinin yazımı yanlıştır?', 'I', ['II', 'III', 'IV'], 'Arapça kökenli sözcük "ihtiyaç" biçiminde yazılır; ünlüyle başlayan ek aldığında da "ç" korunur: ihtiyaçlarımızı.'),
  ('Temizlik kurallarına uyma ve sağlığı koruma anlamındaki sözcüğün doğru yazımı hangisidir?', 'hijyen', ['hicyen', 'hijiyen', 'hijyenn'], 'Fransızca kökenli sözcük "hijyen" biçiminde yazılır.'),
  ('Davetlilere ayakta yiyecek ve içecek sunulan toplantının adı aşağıdakilerin hangisinde doğru yazılmıştır?', 'kokteyl', ['koktel', 'kokteyil', 'kokteyll'], 'İngilizce kökenli sözcüğün yazım kılavuzundaki biçimi "kokteyl"dir.'),
  ('Bir topluluğun ilk yaşadığı, köken aldığı yer anlamındaki sözcük nasıl yazılır?', 'anayurt', ['ana yurt', 'ana-yurt', 'anayürt'], '"anayurt" yazım kılavuzunda bitişik yazılan birleşik addır.'),
  ('Kahvaltıda suyu sıkılarak içilen, portakala benzeyen ekşimsi meyvenin adı aşağıdakilerin hangisinde doğru yazılmıştır?', 'greyfurt', ['greyfrut', 'greyfurd', 'greyyfurt'], 'İngilizce kökenli sözcüğün yazım kılavuzundaki biçimi "greyfurt"tur.'),
  ('Beyaz çiçek kısmı yenen, lahanagillerden bir sebzenin adı nasıl yazılır?', 'karnabahar', ['karnıbahar', 'karnebahar', 'karnabaharr'], 'Yazım kılavuzunda sebzenin adı "karnabahar" biçimindedir.'),
  ('Gıda ve ev eşyası satılan, kendi kendine seçim yapılan büyük mağazanın adı aşağıdakilerin hangisindeki gibi yazılır?', 'süpermarket', ['süper market', 'süper-market', 'supermarket'], 'Yazım kılavuzunda sözcük bitişik ve "ü" ile yazılır: süpermarket.'),
  ('Gömleğin yakasına bağlanan kelebek biçimli kravatın adı nasıl yazılır?', 'papyon', ['papyön', 'papiyon', 'pappyon'], 'Fransızca kökenli sözcüğün yazım kılavuzundaki biçimi "papyon"dur.'),
  ('Roma rakamlarıyla yazılan padişah adlarından söz eden aşağıdaki cümlelerin hangisinde rakam yanlış yazılmıştır?', 'Bağdat\'ı yeniden alan IIII. Murat\'tır.', ['Bağdat\'ı fethetmek için sefere çıkan padişah IV. Murat\'tır.', 'Tanzimat Fermanı Abdülmecit döneminde ilan edilmiştir.', 'Lale Devri III. Ahmet döneminde yaşanmıştır.'], 'Roma rakamlarında dört, beşten bir eksik olarak IV biçiminde yazılır; aynı simge dört kez yan yana yazılmaz.'),
  ('Bir eczane broşüründe ilaç türlerini sayan aşağıdaki sözlerden hangisi yanlış yazılmıştır?', 'antibiotik', ['ağrı kesici', 'öksürük şurubu', 'antiseptik'], 'Bakterilere karşı kullanılan ilaç türü "antibiyotik" biçiminde yazılır; iki ünlü arasına "y" girer.'),
  ('Aşağıdaki cümlelerin hangisinde üç nokta, söylenmesi uygun görülmeyen bir sözün yerini tutmak için kullanılmıştır?', 'Kızgın adam "Seni ... !" diye bağırdı.', ['Bahçede elma, armut, erik... ne ararsan vardı.', 'Keşke o gün yola çıkmasaydık...', 'Ben... ben bunu yapmak istemezdim.'], 'Kaba ya da söylenmek istenmeyen sözlerin yerine üç nokta konur. Öbürlerinde sıralamanın sürdüğü, tamamlanmamış cümle ve duraksama gösterilmiştir.'),
  ('Doğum günü pastasının üstüne küçükcük (I) mumlar dizdik (II), çocuklar bu ufacık (III) mumları tek tek söndürdü (IV). Bu cümlede numaralanmış sözlerden hangisinin yazımı yanlıştır?', 'I', ['II', 'III', 'IV'], '"-cık" küçültme eki "k" ile biten sözcüklere gelirken bu "k" düşer: küçücük, ufacık.'),
  ('Toplumsal yardım ve dayanışmayı anlatan bir haberden alınan aşağıdaki cümlelerin hangisinde "-sever" ile kurulan sözcük kurala aykırı yazılmıştır?', 'Kasabanın hayır sever insanları yeni bir okul yaptırdı.', ['Hayvansever bir komşumuz sokak kedilerini besliyor.', 'Sanatsever izleyiciler salonu doldurdu.', 'Vatansever gençler bayrağı törenle göndere çekti.'], '"-sever" ile kurulan sıfatlar bitişik yazılır: hayırsever.'),
  ('Aşağıdaki cümlelerin hangisinde "üstü" sözcüğünün geçtiği bir söz yanlış yazılmıştır?', 'Takımımız finalde olağan üstü bir performans gösterdi.', ['Hazırlanan film baştan sona doğaüstü olaylar üzerine kuruluydu.', 'Akşamüstü parkta yürüyüşe çıktık.', 'Bu kitabın üstü toz içindeydi.'], 'Kalıplaşmış "olağanüstü" sıfatı bitişik yazılır; "kitabın üstü" ise kendi anlamındaki bir ad tamlamasıdır.'),
  ('"Abur cubur yiyerek akşam yemeğini kaçırdı." cümlesindeki ikilemenin yazımıyla ilgili aşağıdakilerden hangisi doğrudur?', 'Doğrudur; anlamsız bir sözcükle kurulan ikilemeler de ayrı yazılır.', ['Yanlıştır; anlamsız sözcük içeren ikilemeler bitişik yazılmalıdır.', 'Yanlıştır; ikilemeyi oluşturan sözcükler arasına virgül konmalıdır.', 'Yanlıştır; ikilemeyi oluşturan sözcükler kısa çizgiyle bağlanmalıdır.'], 'Sözcüklerden biri anlamsız olsa da ikilemeler ayrı yazılır ve aralarına noktalama işareti konmaz.'),
  ('Maçın son dakikasında hakem (I) önce ofsayd (II) işaretini kaldırdı, ardından penaltı (III) kararını iptal etti (IV). Bu cümlede numaralanmış sözlerden hangisinin yazımı yanlıştır?', 'II', ['I', 'III', 'IV'], 'İngilizce kökenli futbol terimi Türkçede "ofsayt" biçiminde yazılır.'),
  ('Atom çekirdeğinde bulunan, elektrik yükü taşımayan parçacığın adı aşağıdakilerin hangisinde doğru yazılmıştır?', 'nötron', ['nötrön', 'notron', 'nötronn'], 'Sözcüğün doğru yazımı "nötron"dur.'),
  ('Dünya\'yı kuzey ve güney yarım kürelere ayıran hayalî çemberin adı aşağıdakilerin hangisinde doğru yazılmıştır?', 'ekvator', ['ekvatör', 'ekuvator', 'ekvatorr'], 'Yazım kılavuzunda sözcük "ekvator" biçimindedir.'),
  ('Matematik dersinde önce bir sayının kare kökünü (I) bulduk, sonra denklemdeki katsayıları (II) sadeleştirip sonucu (III) tahtaya yazdık (IV). Bu cümlede numaralanmış sözlerden hangisinin yazımı yanlıştır?', 'I', ['II', 'III', 'IV'], 'Matematik terimi olan "karekök" kalıplaşmış birleşik sözcüktür ve bitişik yazılır; "katsayı" da bitişiktir.'),
  ('Kandaki şeker düzeyinin yükselmesiyle görülen hastalığın adı aşağıdakilerin hangisinde doğru yazılmıştır?', 'diyabet', ['diabet', 'diyabed', 'diyyabet'], 'Yazım kılavuzunda sözcük iki ünlü arasına "y" girerek "diyabet" biçiminde yazılır.'),
  ('Kâğıtları bir arada tutmaya yarayan küçük tel kıskacın adı nasıl yazılır?', 'ataç', ['ataş', 'attaç', 'atac'], 'Fransızca kökenli sözcük "ataç" biçiminde yazılır.'),
  ('Gözün renkli bölümünün ortasındaki ışık alan deliğin adı aşağıdakilerin hangisinde doğru yazılmıştır?', 'gözbebeği', ['göz bebeği', 'göz-bebeği', 'gözbebekleri\''], 'Göz organının bir bölümünü adlandıran "gözbebeği" kalıplaşmış birleşik sözcüktür ve bitişik yazılır.'),
  ('Omurga kanalının içinde bulunan sinir dokusunun adı aşağıdakilerin hangisindeki gibi yazılır?', 'omurilik', ['omur ilik', 'omur-ilik', 'omurrilik'], '"omurilik" kalıplaşmış birleşik addır ve bitişik yazılır.'),
  ('Hızlı ve kesintisiz ulaşım için yapılmış, giriş çıkışları denetimli yolun adı yazım kılavuzuna göre nasıl yazılır?', 'otoyol', ['oto yol', 'oto-yol', 'otoyolu\''], 'Yazım kılavuzunda "otoyol" bitişik yazılır; "otopark, otogar" da bitişiktir.'),
  ('Haritalarda kutuplar arasında uzanan ve boylamları gösteren hayalî yarım çemberlerin adı nasıl yazılır?', 'meridyen', ['meridiyen', 'meridyan', 'merridyen'], 'Fransızca kökenli sözcüğün doğru yazımı "meridyen"dir.'),
  ('Bir sayının belirli bir tabana göre üssünü veren matematik işleminin adı aşağıdakilerin hangisinde doğru yazılmıştır?', 'logaritma', ['logaritima', 'lögaritma', 'logarritma'], 'Sözcük yazım kılavuzunda "logaritma" biçimindedir.'),
  ('Soluk borusunun dallarındaki iltihaplanmanın adı aşağıdakilerin hangisinde doğru yazılmıştır?', 'bronşit', ['bronşüt', 'bronşid', 'bırönşit'], 'Sözcüğün doğru yazımı "bronşit"tir.'),
  ('Çocukluk çağında sık görülen bulaşıcı hastalıkları sayan aşağıdaki cümlelerin hangisinde yazım yanlışı vardır?', 'Kardeşim geçen kış su çiçeği geçirdi.', ['Kabakulak aşısı okulda yapıldı.', 'Kızamık salgını yüzünden okullar tatil edildi.', 'Doktor, çocuğun ateşinin düştüğünü söyledi.'], 'Hastalık adı olarak kalıplaşan "suçiçeği" bitişik yazılır; "kabakulak" da bitişiktir.'),
  ('Biyoloji dersinde önce akciğerlerin (I) yapısını, sonra atar damarların (II) ve toplardamarların (III) görevlerini öğrendik; konu karaciğerle (IV) sona erdi. Bu cümlede numaralanmış sözlerden hangisinin yazımı yanlıştır?', 'II', ['I', 'III', 'IV'], 'Kanı kalpten vücuda taşıyan damarın adı kalıplaşmış birleşik sözcüktür ve bitişik yazılır: atardamar.'),
  ('Denizde yüzen, büyük bölümü suyun altında kalan dev buz kütlesinin adı nasıl yazılır?', 'buzdağı', ['buz dağı', 'buz-dağı', 'buzdağıı'], 'Yazım kılavuzunda "buzdağı" bitişik yazılan birleşik addır.'),
  ('Gizli olarak var olan, henüz ortaya çıkmamış güç anlamındaki sözcük nasıl yazılır?', 'potansiyel', ['potensiyel', 'potansiyal', 'pontansiyel'], 'Sözcüğün yazım kılavuzundaki biçimi "potansiyel"dir.'),
  ('Bir işi yapmak için duyulan istek ve güdülenme anlamındaki sözcük aşağıdakilerin hangisinde doğru yazılmıştır?', 'motivasyon', ['motivosyon', 'motivayson', 'mottivasyon'], 'Fransızca kökenli sözcük "motivasyon" biçiminde yazılır.'),
  ('Saygınlık, itibar anlamındaki Fransızca kökenli sözcüğün doğru yazımı hangisidir?', 'prestij', ['prestiş', 'presdij', 'prestijj'], 'Sözcük yazım kılavuzunda "prestij" biçimindedir.'),
  ('Ekin başına, iki yer adının arasına ya da iki yılın arasına konan kısa çizgiler düşünüldüğünde aşağıdakilerin hangisinde kısa çizgi ötekilerden farklı bir görev üstlenmiştir?', '"-lık" eki eklendiği sözcüğe yeni bir anlam katar.', ['Ankara-Sivas karayolu yeniden yapıldı.', 'Birinci Dünya Savaşı 1914-1918 yılları arasında sürdü.', 'İzmir-Aydın otobüsü yarım saat gecikti.'], 'Öbür cümlelerde kısa çizgi "ile ... arasında" anlamı vermek için kullanılmıştır. Ekin başındaki kısa çizgi ise onun bir ek olduğunu gösterir.'),
  ('Çocuklar bahçede önce körebe (I) oynadı, sonra birdirbir (II) yaptılar; akşam ise içeride yap boz (III) parçalarını birleştirip saklambaç (IV) için yeniden dışarı çıktılar. Bu cümlede numaralanmış oyun adlarından hangisinin yazımı yanlıştır?', 'III', ['I', 'II', 'IV'], 'Oyun ve oyuncak adı olarak kalıplaşan "yapboz" bitişik yazılır; "körebe, birdirbir, saklambaç" da bitişiktir.'),
  ('Köyde çocuklar kör ebe (I) oynarken büyükler (II) çelik çomak (III) oyununu izleyip eski günleri (IV) anıyordu. Bu cümlede numaralanmış sözlerden hangisinin yazımı yanlıştır?', 'I', ['II', 'III', 'IV'], 'Bir oyunun adı olan "körebe" anlam kaymasıyla oluşmuş birleşik sözcüktür ve bitişik yazılır.'),
  ('Tiyatroda sahnenin arka tarafında kalan, oyuncuların hazırlandığı bölümün adı aşağıdakilerin hangisinde doğru yazılmıştır?', 'kulis', ['kuliss', 'külis', 'kuliz'], 'Fransızca kökenli sözcük "kulis" biçiminde yazılır.'),
  ('Yünden ya da pamuktan dokunmuş, üstü örtmeye yarayan kalın örtünün adı nasıl yazılır?', 'battaniye', ['battanye', 'bataniye', 'battaniyye'], 'İngilizce kökenli sözcük iki "t" ile "battaniye" biçiminde yazılır.'),
  ('Yorgan ve yastıkların dış kılıfı olarak kullanılan takımın adı aşağıdakilerin hangisinde doğru yazılmıştır?', 'nevresim', ['nevrasim', 'nevresimm', 'nevrezim'], 'Sözcüğün doğru yazımı "nevresim"dir.'),
  ('Tavuk göğsü tatlısının tepsinin dibinde hafifçe yakılmasıyla yapılan tatlının adı aşağıdakilerin hangisinde doğru yazılmıştır?', 'kazandibi', ['kazan dibi', 'kazan-dibi', 'kazandipi'], 'Bir tatlıyı adlandıran "kazandibi" kalıplaşmış birleşik sözcüktür ve bitişik yazılır.'),
  ('Bayram sofrasında baklava (I), hanım göbeği (II), aşure (III) ve künefe (IV) gibi pek çok tatlı vardı. Bu cümlede numaralanmış tatlı adlarından hangisinin yazımı yanlıştır?', 'II', ['I', 'III', 'IV'], 'Anlam kaymasıyla oluşmuş tatlı adları bitişik yazılır: hanımgöbeği.'),
  ('Başarılı bir iş yapanı övmek için söylenen ünlem aşağıdakilerin hangisinde yazım kılavuzuna uygun yazılmıştır?', 'aferin', ['aferim', 'afferin', 'aferinn'], 'Yazım kılavuzunda bu ünlem "aferin" biçimindedir.'),
  ('Muharrem ayında buğday, kuru meyve ve baklagillerle yapılan tatlının adı aşağıdakilerin hangisinde doğru yazılmıştır?', 'aşure', ['aşüre', 'aşurre', 'haşure'], 'Arapça kökenli sözcüğün doğru yazımı "aşure"dir.'),
